function checkHit() {
  if (state.phase !== 'play' || state.invincible > 0) return;
  const i = idx(state.px, state.py);
  if (state.tiles[i] === 'G') return;
  if (redMap()[i] !== 2) return;
  state.lives--;
  state.hits++;
  state.invincible = INVINCIBLE_TIME;
  sfx.hit();
