file.content:
// ── 입력 ──
// 스와이프: 손을 떼지 않고 계속 끌면 여러 칸 이동 (8방향)
// 탭: 탭한 칸 방향으로 한 칸 이동
const SWIPE = 26;
const DIAGONAL_MIN = 25; // 수평에서 25°~65° 사이일 때만 대각선 (살짝 비스듬한 상하좌우 스와이프는 그대로 직선)
const DIAGONAL_MAX = 65;
function move8(dx, dy) {
  const angle = Math.atan2(Math.abs(dy), Math.abs(dx)) * 180 / Math.PI;
  if (angle < DIAGONAL_MIN) move(Math.sign(dx), 0);
  else if (angle > DIAGONAL_MAX) move(0, Math.sign(dy));
  else move(Math.sign(dx), Math.sign(dy));
}
let touch = null;
boardWrap.addEventListener('pointerdown', (e) => {
  touch = { x: e.clientX, y: e.clientY, moved: false };
  boardWrap.setPointerCapture(e.pointerId);
});
boardWrap.addEventListener('pointermove', (e) => {
  if (!touch) return;
  const dx = e.clientX - touch.x;
  const dy = e.clientY - touch.y;
  if (Math.hypot(dx, dy) < SWIPE) return;
  move8(dx, dy);
  touch = { x: e.clientX, y: e.clientY, moved: true };
});
boardWrap.addEventListener('pointerup', (e) => {
  if (touch && !touch.moved && state) {
    const r = board.getBoundingClientRect();
    const cx = (e.clientX - r.left) / (r.width / COLS) - 0.5;
    const cy = (e.clientY - r.top) / (r.height / ROWS) - 0.5;
    const dx = cx - state.px;
    const dy = cy - state.py;
    if (Math.max(Math.abs(dx), Math.abs(dy)) >= 0.5) move8(dx, dy);
  }
  touch = null;
});
boardWrap.addEventListener('pointercancel', () => { touch = null; });

