.cell { position: relative; }
.cell::before {
  content: "";
  position: absolute;
  inset: 3px;
  border-radius: 6px;
  background: #0d0f1c;
  border: 1px solid #1a1f38;
  transition: background 0.08s, box-shadow 0.08s;
}
.cell.hole::before { background: transparent; border-color: transparent; }
.cell.blue::before { background: var(--blue); border-color: #7fb0ff; box-shadow: 0 0 14px rgba(47, 123, 255, 0.8); }
.cell.blue.moving::before { animation: warn 0.12s infinite alternate; }
.cell.done::before { background: #142046; border-color: #24366e; }
.cell.green::before { background: rgba(43, 255, 136, 0.85); border-color: #a5ffcc; box-shadow: 0 0 14px rgba(43, 255, 136, 0.7); }
.cell.warn::before { background: rgba(255, 45, 85, 0.25); border-color: rgba(255, 45, 85, 0.6); animation: warn 0.25s infinite alternate; }
.cell.red::before { background: var(--red); border-color: #ff9bb0; box-shadow: 0 0 16px rgba(255, 45, 85, 0.9); }
.cell.pop::after {
  content: "";
  position: absolute;
  inset: 3px;
  border-radius: 6px;
  border: 2px solid var(--cyan);
  animation: pop 0.35s ease-out forwards;
  pointer-events: none;
}

.player {
  position: absolute;
  left: 0;
  top: 0;
  width: calc(100% / var(--cols));
  height: calc(100% / var(--rows));
  transition: transform 0.08s ease-out;
  pointer-events: none;
  z-index: 2;
}
.player::before {
  content: "";
  position: absolute;
  inset: 22%;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 0 3px var(--cyan), 0 0 18px var(--cyan);
}
.player.invincible { animation: blink 0.15s infinite alternate; }

.countdown {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  font-weight: 900;
  color: #fff;
  text-shadow: 0 0 20px var(--cyan);
  pointer-events: none;
  z-index: 3;
}

.hint { text-align: center; color: var(--muted); font-size: 12px; letter-spacing: 0.2em; margin: 10px 0 0; }

/* ── 모달 ── */
.modal {
  position: fixed;
  inset: 0;
  background: rgba(4, 4, 10, 0.8);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 10;
}
.panel {
  width: 100%;
  max-width: 320px;
  background: var(--panel);
  border: 1px solid var(--cyan);
  border-radius: 16px;
  padding: 24px;
  text-align: center;
  box-shadow: 0 0 30px rgba(45, 226, 255, 0.3);
}
.panel h2 { margin: 0 0 8px; letter-spacing: 0.15em; color: var(--cyan); }
.panel h2.fail { color: var(--red); }
.panel p { color: var(--muted); margin: 8px 0 18px; }
.header-right { display: flex; align-items: center; gap: 8px; }
button:disabled { opacity: 0.3; }
.footer { display: flex; align-items: center; justify-content: center; gap: 16px; }
.footer a { color: var(--muted); font-size: 11px; letter-spacing: 0.15em; text-decoration: none; }

/* ── 랭킹 ── */
.rank-line { color: var(--text) !important; letter-spacing: 0.15em; }
.rank-line b { color: #ffd84a; font-size: 22px; }
.rank-nav { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; letter-spacing: 0.15em; color: var(--cyan); }
.rank-list { list-style: none; margin: 0; padding: 0; text-align: left; max-height: 42vh; overflow-y: auto; }
.rank-list li { display: grid; grid-template-columns: 28px 1fr auto; gap: 8px; padding: 7px 8px; border-bottom: 1px solid var(--line); font-size: 15px; }
.rank-list li span:first-child { color: var(--muted); }
.rank-list li span:nth-child(2) { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rank-list li span:last-child { font-variant-numeric: tabular-nums; }
.rank-list li:nth-child(-n+3) span:first-child { color: #ffd84a; font-weight: 800; }
.rank-list li.me { background: rgba(45, 226, 255, 0.12); border-radius: 6px; }
.rank-list li.empty { display: block; text-align: center; color: var(--muted); letter-spacing: 0.15em; border: 0; }
.panel .rank-me { margin: 10px 0; font-size: 13px; letter-spacing: 0.1em; }
.name-row { display: flex; gap: 8px; margin-bottom: 14px; }
.name-row input {
  flex: 1; min-width: 0; font: inherit; font-size: 16px; color: var(--text);
  background: var(--bg); border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px;
  user-select: text; -webkit-user-select: text;
}
.name-row input:focus { outline: none; border-color: var(--cyan); }

.stars { font-size: 34px; color: #ffd84a; letter-spacing: 6px; min-height: 0; }
.stars .off { color: #2a2f4a; }
.buttons { display: flex; flex-direction: column; gap: 10px; }

@keyframes pop { from { transform: scale(1); opacity: 1; } to { transform: scale(1.5); opacity: 0; } }
@keyframes warn { from { opacity: 0.4; } to { opacity: 1; } }
@keyframes blink { from { opacity: 1; } to { opacity: 0.2; } }
@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-6px); }
  75% { transform: translateX(6px); }
}

