// 스테이지 검사: 크기, 시작점, 초록 유무, 빨강 시작 위치, 파랑 도달 가능 여부
const fs = require('fs');
eval(fs.readFileSync(process.argv[2], 'utf8') + ';global.S=STAGES;global.T=TIERS');
let bad = 0;
const W = 6, H = 8;
S.forEach((s, n) => {
  const m = s.map;
  const err = [];
  if (m.length !== H || m.some((r) => r.length !== W)) err.push('size');
  let px, py, pc = 0;
  m.forEach((r, y) => [...r].forEach((c, x) => { if (c === 'P') { px = x; py = y; pc++; } }));
  if (pc !== 1) err.push('P count');
  const at = (x, y) => (x >= 0 && x < W && y >= 0 && y < H ? m[y][x] : null);
  if (!m.join('').includes('G')) err.push('no green');
  const hw = (x, y) => { const c = at(x, y); return c !== null && c !== '#' && c !== 'G'; };
  s.hazards.forEach((h) => {
    if (h.type === 'sweep') return;
    if (!hw(h.x, h.y)) err.push('hazard start bad ' + JSON.stringify(h));
    if (Math.max(Math.abs(h.x - px), Math.abs(h.y - py)) <= 1) err.push('hazard near P ' + JSON.stringify(h));
    if (h.type === 'bounce' && ![[h.dx, h.dy], [-h.dx, h.dy], [h.dx, -h.dy], [-h.dx, -h.dy]]
      .some(([a, b]) => (a || b) && hw(h.x + a, h.y + b))) err.push('bounce stuck');
  });
  const seen = new Set([px + ',' + py]);
  const q = [[px, py]];
  while (q.length) {
    const [x, y] = q.shift();
    for (let dx = -1; dx <= 1; dx++) for (let dy = -1; dy <= 1; dy++) {
      const c = at(x + dx, y + dy);
      const k = (x + dx) + ',' + (y + dy);
      if (c && c !== '#' && !seen.has(k)) { seen.add(k); q.push([x + dx, y + dy]); }
    }
  }
  m.forEach((r, y) => [...r].forEach((c, x) => { if (c === 'B' && !seen.has(x + ',' + y)) err.push('unreachable B ' + x + ',' + y); }));
  if (/[ab]/.test(m.join('')) && !s.blink) err.push('blink cells but no blink cfg');
  const blue = (m.join('').match(/B/g) || []).length;
  const tier = n < 12 ? 'E' : n < 24 ? 'N' : 'H';
  console.log(`${tier}${n % 12 + 1}`.padEnd(4), 'time', s.time, 'blue', String(blue).padStart(2), 'red', s.hazards.length,
    'shuffle', JSON.stringify(s.shuffle ?? 5), err.length ? '  !! ' + err.join('; ') : '');
  bad += err.length;
});
console.log('total', S.length, 'tiers', T.map((t) => t.name + ':' + t.stages.length).join(' '), 'errors', bad);

