toolUseResult.originalFile:
:root {
  --bg: #07070f;
  --panel: #10121f;
  --line: #1f2440;
  --text: #e8ecff;
  --muted: #7a82a8;
  --cyan: #2de2ff;
  --blue: #2f7bff;
  --red: #ff2d55;
  --green: #2bff88;
  --cols: 6;
  --rows: 8;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  user-select: none;
  -webkit-user-select: none;
  overflow: hidden;
}

body {
  background:
    radial-gradient(ellipse at 50% -10%, rgba(45, 226, 255, 0.12), transparent 60%),
    var(--bg);
}

.app {
  max-width: 480px;
  height: 100dvh;
  margin: 0 auto;
  padding: max(12px, env(safe-area-inset-top)) 16px max(12px, env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
}

.hidden { display: none !important; }

button {
  font: inherit;
  color: var(--text);
  background: var(--blue);
  border: 0;
  border-radius: 10px;
  padding: 12px 18px;
  font-weight: 700;
  letter-spacing: 0.05em;
  cursor: pointer;
  box-shadow: 0 0 14px rgba(47, 123, 255, 0.5);
}
button:active { transform: scale(0.96); }
button.secondary { background: var(--panel); border: 1px solid var(--line); box-shadow: none; }
button.icon { width: 44px; height: 44px; padding: 0; }
button.small { padding: 8px 14px; font-size: 13px; align-self: center; }

.box {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 6px 12px;
  text-align: center;
  min-width: 72px;
}
.box label { display: block; font-size: 10px; color: var(--muted); letter-spacing: 0.15em; }
.box b { font-size: 20px; }

/* ── 스테이지 선택 ── */
header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 8px 0 20px;
}
h1 {
  margin: 0;
  font-size: 30px;
  letter-spacing: 0.08em;
  color: var(--cyan);
  text-shadow: 0 0 12px rgba(45, 226, 255, 0.7);
}
h1 span { color: var(--red); text-shadow: 0 0 12px rgba(255, 45, 85, 0.7); margin-left: 4px; }

.stage-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  overflow-y: auto;
}
.stage-btn {
  aspect-ratio: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 0;
  font-size: 22px;
  background: var(--panel);
  border: 1px solid var(--cyan);
  box-shadow: 0 0 10px rgba(45, 226, 255, 0.25), inset 0 0 10px rgba(45, 226, 255, 0.1);
}
.stage-btn small { font-size: 11px; color: #ffd84a; letter-spacing: 1px; }
.stage-btn.locked { border-color: var(--line); color: var(--muted); box-shadow: none; }
.stage-btn.locked small { color: var(--muted); }

.legend {
  display: flex;
  justify-content: center;
  gap: 22px;
  margin: auto 0 16px;
  padding-top: 20px;
}
.legend div { display: flex; flex-direction: column; align-items: center; gap: 6px; font-size: 11px; color: var(--muted); letter-spacing: 0.1em; }
.legend .tile { display: block; width: 34px; height: 34px; border-radius: 6px; }
.tile.blue { background: var(--blue); box-shadow: 0 0 12px var(--blue); }
.tile.red { background: var(--red); box-shadow: 0 0 12px var(--red); }
.tile.green { background: var(--green); box-shadow: 0 0 12px var(--green); }

/* ── 게임 화면 ── */
.topbar { display: flex; align-items: center; justify-content: space-between; }
.stage-name { font-weight: 800; letter-spacing: 0.15em; color: var(--cyan); }

.hud { display: flex; justify-content: space-between; gap: 8px; margin: 12px 0 8px; }
.hud .box { flex: 1; }
.lives { color: var(--red); letter-spacing: 2px; }

.timebar { height: 6px; background: var(--panel); border-radius: 3px; overflow: hidden; }
#timeFill { height: 100%; width: 100%; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); transition: width 0.2s linear; }
#timeFill.low { background: var(--red); box-shadow: 0 0 8px var(--red); }

.board-wrap {
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  touch-action: none;
}
.board {
  position: relative;
  display: grid;
  grid-template-columns: repeat(var(--cols), 1fr);
  grid-template-rows: repeat(var(--rows), 1fr);
  /* 크기는 game.js의 resizeBoard()가 비율에 맞춰 지정 */
}
.board.shake { animation: shake 0.3s; }

/* 칸 사이 간격은 ::before 안쪽 여백으로 (플레이어 위치 계산을 단순하게) */
.cell { position: relative; }
.cell::before {
  content: "";
  position: absolute;
  inset: 3px;
  border-radius: 6px;
  background: #0d0f1c;
  border: 1px solid #1a1f38;
  transition: background 0.08s, box-shadow 0.08s;
}
.cell.hole::before { background: transparent; border-color: transparent; }
.cell.blue::before { background: var(--blue); border-color: #7fb0ff; box-shadow: 0 0 14px rgba(47, 123, 255, 0.8); }
.cell.blue.moving::before { animation: warn 0.12s infinite alternate; }
.cell.done::before { background: #142046; border-color: #24366e; }
.cell.green::before { background: rgba(43, 255, 136, 0.85); border-color: #a5ffcc; box-shadow: 0 0 14px rgba(43, 255, 136, 0.7); }
.cell.warn::before { background: rgba(255, 45, 85, 0.25); border-color: rgba(255, 45, 85, 0.6); animation: warn 0.25s infinite alternate; }
.cell.red::before { background: var(--red); border-color: #ff9bb0; box-shadow: 0 0 16px rgba(255, 45, 85, 0.9); }
.cell.pop::after {
  content: "";
  position: absolute;
  inset: 3px;
  border-radius: 6px;
  border: 2px solid var(--cyan);
  animation: pop 0.35s ease-out forwards;
  pointer-events: none;
}

.player {
  position: absolute;
  left: 0;
  top: 0;
  width: calc(100% / var(--cols));
  height: calc(100% / var(--rows));
  /* 미끄러지듯 감속하는 곡선. 이동 중에 다음 이동이 들어오면 현재 위치에서 자연스럽게 이어짐 */
  transition: transform 0.12s cubic-bezier(0.25, 0.8, 0.35, 1);
  pointer-events: none;
  z-index: 2;
}
.player.diag { transition-duration: 0.16s; }
.player::before {
  content: "";
  position: absolute;
  inset: 22%;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 0 3px var(--cyan), 0 0 18px var(--cyan);
}
.player.invincible { animation: blink 0.15s infinite alternate; }

.countdown {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  font-weight: 900;
  color: #fff;
  text-shadow: 0 0 20px var(--cyan);
  pointer-events: none;
  z-index: 3;
}

.hint { text-align: center; color: var(--muted); font-size: 12px; letter-spacing: 0.2em; margin: 10px 0 0; }

/* ── 모달 ── */
.modal {
  position: fixed;
  inset: 0;
  background: rgba(4, 4, 10, 0.8);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 10;
}
.panel {
  width: 100%;
  max-width: 320px;
  background: var(--panel);
  border: 1px solid var(--cyan);
  border-radius: 16px;
  padding: 24px;
  text-align: center;
  box-shadow: 0 0 30px rgba(45, 226, 255, 0.3);
}
.panel h2 { margin: 0 0 8px; letter-spacing: 0.15em; color: var(--cyan); }
.panel h2.fail { color: var(--red); }
.panel p { color: var(--muted); margin: 8px 0 18px; }
.header-right { display: flex; align-items: center; gap: 8px; }
button:disabled { opacity: 0.3; }
.footer { display: flex; align-items: center; justify-content: center; gap: 16px; }
.footer a { color: var(--muted); font-size: 11px; letter-spacing: 0.15em; text-decoration: none; }

/* ── 랭킹 ── */
.rank-line { color: var(--text) !important; letter-spacing: 0.15em; }
.rank-line b { color: #ffd84a; font-size: 22px; }
.rank-nav { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; letter-spacing: 0.15em; color: var(--cyan); }
.rank-list { list-style: none; margin: 0; padding: 0; text-align: left; max-height: 42vh; overflow-y: auto; }
.rank-list li { display: grid; grid-template-columns: 28px 1fr auto; gap: 8px; padding: 7px 8px; border-bottom: 1px solid var(--line); font-size: 15px; }
.rank-list li span:first-child { color: var(--muted); }
.rank-list li span:nth-child(2) { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rank-list li span:last-child { font-variant-numeric: tabular-nums; }
.rank-list li:nth-child(-n+3) span:first-child { color: #ffd84a; font-weight: 800; }
.rank-list li.me { background: rgba(45, 226, 255, 0.12); border-radius: 6px; }
.rank-list li.empty { display: block; text-align: center; color: var(--muted); letter-spacing: 0.15em; border: 0; }
.panel .rank-me { margin: 10px 0; font-size: 13px; letter-spacing: 0.1em; }
.name-row { display: flex; gap: 8px; margin-bottom: 14px; }
.name-row input {
  flex: 1; min-width: 0; font: inherit; font-size: 16px; color: var(--text);
  background: var(--bg); border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px;
  user-select: text; -webkit-user-select: text;
}
.name-row input:focus { outline: none; border-color: var(--cyan); }

.stars { font-size: 34px; color: #ffd84a; letter-spacing: 6px; min-height: 0; }
.stars .off { color: #2a2f4a; }
.buttons { display: flex; flex-direction: column; gap: 10px; }

@keyframes pop { from { transform: scale(1); opacity: 1; } to { transform: scale(1.5); opacity: 0; } }
@keyframes warn { from { opacity: 0.4; } to { opacity: 1; } }
@keyframes blink { from { opacity: 1; } to { opacity: 0.2; } }
@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-6px); }
  75% { transform: translateX(6px); }
}

input.content:
// 시연 화면: 미니 판(5×5)에서 규칙을 장면별로 자동 재생
// - 실제 게임과 같은 타일 스타일(.cell .blue/.red/.green ...)을 그대로 씀
// - window.Demo.start(onDone) / window.Demo.stop()
(() => {
  const N = 5;
  const $ = (id) => document.getElementById(id);
  const boardEl = $('demoBoard');
  const playerEl = $('demoPlayer');
  const swipeEl = $('demoSwipe');
  const badgeEl = $('demoBadge');

  // 장면: title/sub = 설명, map = 판 ('.' 바닥, 'B' 파랑, 'G' 초록), player = 시작 위치
  //       steps = [[이전 단계 후 대기(ms), (d) => 동작], ...]
  const SCENES = [
    {
      title: 'SWIPE TO MOVE',
      sub: '8 directions  ↑ ↓ ← → ↖ ↗ ↙ ↘',
      map: ['.....', '.....', '.....', '.....', '.....'],
      player: [2, 2],
      steps: [
        [700, (d) => d.move(0, -1)],
        [650, (d) => d.move(1, 0)],
        [650, (d) => d.move(0, 1)],
        [650, (d) => d.move(-1, 1)],
        [650, (d) => d.move(-1, -1)],
        [650, (d) => d.move(1, -1)],
      ],
    },
    {
      title: 'STEP ON ALL BLUE',
      sub: 'Turn every blue tile off',
      map: ['.....', '.B...', '...B.', '.B...', '.....'],
      player: [2, 4],
      hud: { blue: true },
      steps: [
        [700, (d) => d.move(-1, -1)],
        [600, (d) => d.move(0, -1)],
        [600, (d) => d.move(0, -1)],
        [600, (d) => d.move(1, 1)],
        [600, (d) => d.move(1, 0)],
        [300, (d) => d.badge('CLEAR!', 'good')],
      ],
    },
    {
      title: 'AVOID RED',
      sub: 'Red tiles move. Time your step',
      map: ['..B..', '.....', '.....', '.....', '.....'],
      player: [2, 4],
      hud: { blue: true },
      steps: [
        [300, (d) => d.red([[0, 2]])],
        [450, (d) => d.move(0, -1)],
        [300, (d) => d.red([[1, 2]])],
        [450, (d) => d.red([[2, 2]])],
        [450, (d) => d.red([[3, 2]])],
        [200, (d) => d.move(0, -1)],
        [250, (d) => d.red([[4, 2]])],
        [300, (d) => d.move(0, -1)],
        [200, (d) => d.red([[3, 2]])],
        [300, (d) => d.move(0, -1)],
        [200, (d) => d.red([[2, 2]])],
        [300, (d) => d.badge('NICE!', 'good')],
      ],
    },
    {
      title: 'RED = LOSE A LIFE',
      sub: '3 lives. Lose them all and it\'s over',
      map: ['.....', '.....', '.....', '.....', '.....'],
      player: [2, 3],
      hud: { lives: true },
      steps: [
        [0, (d) => d.red([[2, 1]])],
        [700, (d) => d.move(0, -1)],
        [600, (d) => d.move(0, -1)],
        [0, (d) => d.hit()],
        [900, (d) => d.move(0, 1)],
      ],
    },
    {
      title: 'GREEN IS SAFE',
      sub: 'Red can\'t enter green. Hide there',
      map: ['.....', '.....', '..G..', '.....', '.....'],
      player: [2, 3],
      steps: [
        [300, (d) => d.sweep(0)],
        [500, (d) => d.sweep(1)],
        [150, (d) => d.move(0, -1)],
        [350, (d) => d.sweep(2)],
        [100, (d) => d.badge('SAFE', 'good')],
        [400, (d) => d.sweep(3)],
        [500, (d) => d.sweep(4)],
        [500, (d) => d.red([])],
      ],
    },
    {
      title: 'BLUE TELEPORTS!',
      sub: 'Blue blinks, then jumps to a new spot',
      map: ['.....', '.B...', '.....', '...B.', '.....'],
      player: [2, 4],
      hud: { blue: true },
      steps: [
        [700, (d) => d.warnBlue(true)],
        [1100, (d) => { d.warnBlue(false); d.teleport([[1, 1], [3, 3]], [[1, 3], [3, 1]]); }],
        [600, (d) => d.move(-1, -1)],
        [550, (d) => d.move(1, -1)],
        [550, (d) => d.move(1, -1)],
        [300, (d) => d.badge('CLEAR!', 'good')],
      ],
    },
    {
      title: 'BEAT THE CLOCK',
      sub: 'Clear before time runs out. Fewer hits = more ★',
      map: ['.....', '..B..', '.....', '.....', '.....'],
      player: [2, 3],
      hud: { blue: true, timer: true },
      steps: [
        [50, (d) => d.timer(0.45)],
        [650, (d) => d.move(0, -1)],
        [550, (d) => d.move(0, -1)],
        [300, (d) => d.badge('★★★', 'stars')],
      ],
    },
  ];

  let cells = [];
  let d = null;        // 현재 장면 상태
  let timers = [];
  let current = 0;
  let onDone = null;

  function build() {
    boardEl.querySelectorAll('.cell').forEach((c) => c.remove());
    cells = [];
    for (let i = 0; i < N * N; i++) {
      const c = document.createElement('div');
      c.className = 'cell';
      boardEl.insertBefore(c, playerEl);
      cells.push(c);
    }
  }

  function render() {
    const red = new Set(d.red.map(([x, y]) => y * N + x));
    cells.forEach((c, i) => {
      const t = d.tiles[i];
      let cls = 'cell';
      if (t === 'G') cls += ' green';
      else if (red.has(i)) cls += ' red';
      else if (t === 'B') cls += d.warn ? ' blue moving' : ' blue';
      else if (t === 'D') cls += ' done';
      if (d.pops.has(i)) cls += ' pop';
      c.className = cls;
    });
    playerEl.style.transform = `translate(${d.px * 100}%, ${d.py * 100}%)`;
    $('demoBlue').textContent = `BLUE ${d.tiles.filter((t) => t === 'B').length}`;
    $('demoLives').textContent = '♥'.repeat(d.lives) + '♡'.repeat(3 - d.lives);
  }

  // 장면에서 쓰는 동작들
  const actions = {
    move(dx, dy) {
      // 스와이프 화살표를 보여주고 이동
      const angle = Math.atan2(dy, dx) * 180 / Math.PI;
      swipeEl.style.transform = `translate(${d.px * 100}%, ${d.py * 100}%) rotate(${angle}deg)`;
      swipeEl.classList.remove('show');
      void swipeEl.offsetWidth;
      swipeEl.classList.add('show');
      playerEl.classList.toggle('diag', dx !== 0 && dy !== 0);
      d.px += dx;
      d.py += dy;
      const i = d.py * N + d.px;
      if (d.tiles[i] === 'B') {
        d.tiles[i] = 'D';
        d.pops.add(i);
        later(350, () => { d.pops.delete(i); render(); });
      }
      render();
    },
    red(list) { d.red = list; render(); },
    sweep(row) {
      d.red = [];
      for (let x = 0; x < N; x++) if (d.tiles[row * N + x] !== 'G') d.red.push([x, row]);
      render();
    },
    hit() {
      d.lives = Math.max(0, d.lives - 1);
      boardEl.classList.remove('shake');
      void boardEl.offsetWidth;
      boardEl.classList.add('shake');
      playerEl.classList.add('invincible');
      later(1000, () => playerEl.classList.remove('invincible'));
      actions.badge('-♥', 'bad');
      render();
    },
    warnBlue(on) { d.warn = on; render(); },
    teleport(from, to) {
      from.forEach(([x, y], k) => {
        const [tx, ty] = to[k];
        d.tiles[y * N + x] = '.';
        d.tiles[ty * N + tx] = 'B';
        const i = ty * N + tx;
        d.pops.add(i);
        later(350, () => { d.pops.delete(i); render(); });
      });
      render();
    },
    timer(ratio) { $('demoTimeFill').style.width = `${ratio * 100}%`; },
    badge(text, kind) {
      badgeEl.textContent = text;
      badgeEl.className = `demo-badge ${kind}`;
      later(900, () => badgeEl.classList.add('hidden'));
    },
  };

  function later(ms, fn) { timers.push(setTimeout(fn, ms)); }
  function clearTimers() { timers.forEach(clearTimeout); timers = []; }

  function play(i) {
    clearTimers();
    current = i;
    const s = SCENES[i];
    d = {
      tiles: s.map.join('').split(''),
      px: s.player[0],
      py: s.player[1],
      red: [],
      pops: new Set(),
      warn: false,
      lives: 3,
    };
    $('demoTitle').textContent = s.title;
    $('demoSub').textContent = s.sub;
    const hud = s.hud || {};
    $('demoBlue').classList.toggle('hidden', !hud.blue);
    $('demoLives').classList.toggle('hidden', !hud.lives);
    $('demoTimer').classList.toggle('hidden', !hud.timer);
    const fill = $('demoTimeFill');
    fill.style.transition = 'none';
    fill.style.width = '100%';
    void fill.offsetWidth;
    fill.style.transition = '';
    badgeEl.className = 'demo-badge hidden';
    swipeEl.classList.remove('show');
    playerEl.classList.remove('invincible', 'diag');
    // 장면이 바뀔 때 플레이어가 미끄러져 가지 않도록 위치를 바로 지정
    playerEl.style.transition = 'none';
    render();
    void playerEl.offsetWidth;
    playerEl.style.transition = '';

    // 진행 점
    const dots = $('demoDots');
    dots.innerHTML = '';
    SCENES.forEach((_, k) => {
      const dot = document.createElement('button');
      dot.className = 'dot' + (k === i ? ' active' : '');
      dot.setAttribute('aria-label', `Step ${k + 1}`);
      dot.onclick = () => play(k);
      dots.appendChild(dot);
    });
    $('demoPrev').disabled = i === 0;
    $('demoNext').disabled = i === SCENES.length - 1;
    $('demoStart').classList.toggle('pulse', i === SCENES.length - 1);

    // 단계 실행 → 끝나면 잠시 후 다음 장면 (마지막 장면은 그대로 두고 START 강조)
    let t = 0;
    s.steps.forEach(([wait, fn]) => { t += wait; later(t, () => fn(actions)); });
    if (i < SCENES.length - 1) later(t + 1400, () => play(i + 1));
  }

  $('demoPrev').onclick = () => current > 0 && play(current - 1);
  $('demoNext').onclick = () => current < SCENES.length - 1 && play(current + 1);
  const finish = () => { window.Demo.stop(); onDone && onDone(); };
  $('demoStart').onclick = finish;
  $('demoSkip').onclick = finish;

  window.Demo = {
    start(done) {
      onDone = done;
      if (!cells.length) build();
      play(0);
    },
    stop() { clearTimers(); },
  };
})();

