// 배포된 사이트를 폰처럼 열어서 오류·화면 확인
import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const DIR = process.argv[2];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const edge = spawn(EDGE, ['--headless=new', '--disable-gpu', '--no-first-run', `--user-data-dir=${DIR}/edge-mobile`,
  '--remote-debugging-port=9334', '--ignore-certificate-errors', 'about:blank']);
let ws;
try {
  let target;
  for (let i = 0; i < 40 && !target; i++) {
    await sleep(250);
    try { target = (await (await fetch('http://127.0.0.1:9334/json')).json()).find((t) => t.type === 'page'); } catch {}
  }
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r) => ws.addEventListener('open', r));
  let id = 0;
  const pending = new Map();
  const errors = [];
  ws.addEventListener('message', (e) => {
    const m = JSON.parse(e.data);
    if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
    if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text);
    if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') errors.push('console: ' + m.params.args.map((a) => a.value ?? a.description).join(' '));
  });
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.result?.value;
  const shot = async (name) => writeFileSync(`${DIR}/${name}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'));

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
  await send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });
  await send('Emulation.setUserAgentOverride', { userAgent: 'Mozilla/5.0 (Linux; Android 14; SM-S921N) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/129.0 Mobile Safari/537.36' });
  await send('Page.navigate', { url: 'https://stages-861a3.web.app/' });
  await sleep(4000);
  console.log('demo visible:', await ev(`!document.getElementById('demoScreen').classList.contains('hidden')`));
  await ev(`document.getElementById('demoSkip').click()`);
  await sleep(500);
  console.log('mode button:', await ev(`(() => { const b = document.getElementById('modeBtn'); const r = b.getBoundingClientRect(); return b.textContent + ' @ y=' + Math.round(r.top) + ' visible=' + (r.height > 0 && r.top >= 0 && r.bottom <= innerHeight); })()`));
  await shot('m-1-stages');
  await ev(`document.querySelector('#stageGrid .stage-btn').click()`);
  await sleep(2500);
  console.log('cells:', await ev(`document.querySelectorAll('#board .cell').length`), 'board size:', await ev(`(() => { const r = document.getElementById('board').getBoundingClientRect(); return Math.round(r.width) + 'x' + Math.round(r.height); })()`));
  await shot('m-2-game');
  console.log('errors:', errors.length ? errors : 'none');
} catch (e) {
  console.log('ERROR', e.message);
} finally {
  ws?.close();
  edge.kill();
}

