const fs=require('fs');
const patch=(p,rep)=>{let s=fs.readFileSync(p,'utf8');for(const [a,b] of rep){if(s.split(a).length!==2)throw new Error(p+' miss '+a.slice(0,50));s=s.replace(a,()=>b);}fs.writeFileSync(p,s);};

// 금 SVG (몸체와 같이 구름). c1 = 생명 2일 때, c2 = 생명 1일 때 추가
const CRACK = `<svg class="crack" viewBox="0 0 100 100" aria-hidden="true">
            <g class="c1"><path d="M30 8 L38 24 L33 33 L45 44 L50 50 M38 24 L47 19"/></g>
            <g class="c2"><path d="M50 50 L58 60 L55 70 L66 80 L71 92 M50 50 L64 46 L76 51 L92 45 M58 60 L46 69 L40 80"/></g>
          </svg>`;
patch('index.html',[
[`        <div id="player" class="player"></div>`,`        <div id="player" class="player">
          ${CRACK}
        </div>`],
[`        <div id="demoPlayer" class="player"></div>`,`        <div id="demoPlayer" class="player">
          ${CRACK}
        </div>`],
]);

patch('style.css',[[`.player.invincible { animation: blink 0.15s infinite alternate; }`,
`.player.invincible { animation: blink 0.15s infinite alternate; }

/* 금: 생명이 줄 때마다 늘어남 (data-crack = 잃은 생명 수). 몸체와 같이 굴러감 */
.player .crack {
  position: absolute;
  inset: 18%;
  width: 64%;
  height: 64%;
  clip-path: polygon(25% 6.7%, 75% 6.7%, 100% 50%, 75% 93.3%, 25% 93.3%, 0% 50%);
  transform: rotate(var(--rot, 0deg));
  transition: transform 0.16s cubic-bezier(0.3, 0.7, 0.4, 1);
  z-index: 1;
  overflow: visible;
}
.player .crack path {
  fill: none;
  stroke: #142233;
  stroke-width: 3;
  stroke-linejoin: round;
  stroke-linecap: round;
  filter: drop-shadow(1px 1px 0 rgba(255, 255, 255, 0.75)); /* 갈라진 틈의 밝은 단면 */
}
.player .crack g { opacity: 0; transition: opacity 0.1s; }
.player[data-crack="1"] .c1,
.player[data-crack="2"] .c1,
.player[data-crack="2"] .c2 { opacity: 1; }
.player.crack-flash .crack { animation: crack-flash 0.35s ease-out; }

/* 깨짐: 몸체는 숨기고 6조각이 흩어짐 */
.player.shatter::before,
.player.shatter::after,
.player.shatter .crack { opacity: 0; }
.player .shard {
  position: absolute;
  inset: 18%;
  background: linear-gradient(135deg, #f4f9fd, #a9bdcd);
  animation: shard 0.75s cubic-bezier(0.2, 0.7, 0.4, 1) forwards;
}

@keyframes crack-flash { 0% { filter: brightness(2.2); } 100% { filter: brightness(1); } }
@keyframes shard {
  0% { transform: translate(0, 0) rotate(0deg); opacity: 1; }
  100% { transform: translate(var(--dx), var(--dy)) rotate(var(--r)); opacity: 0; }
}`]]);

patch('game.js',[
// 효과음
[`    hit: () => beep(90, 0.3, 'sawtooth', 0.12),`,
`    hit: () => beep(90, 0.3, 'sawtooth', 0.12),
    crack: () => { beep(2400, 0.04, 'square', 0.05); beep(1700, 0.05, 'square', 0.04, 0.03); },
    shatter: () => [2600, 2100, 3000, 1600, 2300, 1200].forEach((f, i) => beep(f, 0.06, 'square', 0.05, i * 0.035)),`],
// 생명 0 → 깨지고 나서 실패
[`    updateHud();
    if (state.lives <= 0) failStage('outOfLife');`,
`    updateHud();
    if (state.lives <= 0) {
      state.phase = 'breaking';
      shatterPlayer();
      setTimeout(() => { if (state && state.phase === 'breaking') failStage('outOfLife'); }, 800);
    } else {
      sfx.crack();
    }`],
// 렌더: 금 단계
[`    playerEl.classList.toggle('invincible', state.invincible > 0);`,
`    playerEl.classList.toggle('invincible', state.invincible > 0);
    const crack = String(Math.min(2, MAX_LIVES - state.lives));
    if (playerEl.dataset.crack !== crack) {
      if (Number(crack) > Number(playerEl.dataset.crack || 0)) {
        playerEl.classList.remove('crack-flash');
        void playerEl.offsetWidth;
        playerEl.classList.add('crack-flash');
      }
      playerEl.dataset.crack = crack;
    }`],
// 이어하기 → 조각 정리 (생명 1 = 큰 금)
[`    if (life) {
      state.lives = cfg.rewardedLife ?? 1;`,
`    if (life) {
      restorePlayer();
      state.lives = cfg.rewardedLife ?? 1;`],
// 새 판 → 조각 정리
[`    $('stageName').textContent = stageLabel(n);`,
`    $('stageName').textContent = stageLabel(n);
    restorePlayer();`],
// 깨짐/복구 함수
[`  // 육각형 굴리기:`,
`  // 육각형 깨짐: 6개 면이 각자 바깥쪽으로 흩어짐
  function shatterPlayer() {
    sfx.shatter();
    vibrate([30, 30, 120]);
    restorePlayer();
    playerEl.classList.add('shatter');
    for (let k = 0; k < 6; k++) {
      // 면 k: 가운데 + 인접한 두 꼭짓점 (꼭짓점은 위에서 시계 방향 30°, 90°, ...)
      const v = (deg) => [50 + 50 * Math.sin(deg * Math.PI / 180), 50 - 50 * Math.cos(deg * Math.PI / 180) * 0.866 / 0.866];
      const hex = [[25, 6.7], [75, 6.7], [100, 50], [75, 93.3], [25, 93.3], [0, 50]];
      const a = hex[k];
      const b = hex[(k + 1) % 6];
      const mid = [(a[0] + b[0]) / 2 - 50, (a[1] + b[1]) / 2 - 50];
      const len = Math.hypot(mid[0], mid[1]);
      const shard = document.createElement('div');
      shard.className = 'shard';
      shard.style.clipPath = \`polygon(50% 50%, \${a[0]}% \${a[1]}%, \${b[0]}% \${b[1]}%)\`;
      shard.style.setProperty('--dx', \`\${(mid[0] / len) * (28 + Math.random() * 16)}px\`);
      shard.style.setProperty('--dy', \`\${(mid[1] / len) * (28 + Math.random() * 16) + 10}px\`);
      shard.style.setProperty('--r', \`\${(Math.random() - 0.5) * 160}deg\`);
      shard.style.rotate = \`\${playerEl.rot || 0}deg\`;
      playerEl.appendChild(shard);
      void v;
    }
  }

  function restorePlayer() {
    playerEl.classList.remove('shatter', 'crack-flash');
    playerEl.querySelectorAll('.shard').forEach((s) => s.remove());
  }

  // 육각형 굴리기:`],
]);

// 시연: 생명이 줄면 금
patch('demo.js',[[`    playerEl.style.transform = \`translate(\${d.px * 100}%, \${d.py * 100}%)\`;`,
`    playerEl.style.transform = \`translate(\${d.px * 100}%, \${d.py * 100}%)\`;
    playerEl.dataset.crack = String(Math.min(2, 3 - d.lives));`]]);
console.log('ok');
EOF
node --check game.js && node --check demo.js && echo syntax-ok

