  // → 매번 다른 모양·크기의 조각 16~22개 + 작은 가루. 좌표는 육각형 상자 기준 % (0~100)
  const HEX_POINTS = [[25, 6.7], [75, 6.7], [100, 50], [75, 93.3], [25, 93.3], [0, 50]];
  const rand = (a, b) => a + Math.random() * (b - a);

  // P에서 각도 a로 뻗은 선이 육각형 테두리와 만나는 점
  function rayToEdge(P, a) {
    const d = [Math.cos(a), Math.sin(a)];
    let best = null;
    HEX_POINTS.forEach((A, k) => {
      const B = HEX_POINTS[(k + 1) % 6];
      const e = [B[0] - A[0], B[1] - A[1]];
      const den = d[0] * e[1] - d[1] * e[0];
      if (Math.abs(den) < 1e-9) return;
      const t = ((A[0] - P[0]) * e[1] - (A[1] - P[1]) * e[0]) / den;
      const u = ((A[0] - P[0]) * d[1] - (A[1] - P[1]) * d[0]) / den;
      if (t > 0 && u >= 0 && u <= 1 && (!best || t < best.t)) best = { t, p: [P[0] + d[0] * t, P[1] + d[1] * t] };
    });
    return best.p;
  }

  function fracture() {
    const P = [50 + rand(-10, 10), 50 + rand(-10, 10)];
    const n = 8 + Math.floor(Math.random() * 4);
    const step = (Math.PI * 2) / n;
    const offset = rand(0, step);
    const rays = [];
    for (let i = 0; i < n; i++) {
      const a = offset + i * step + rand(-0.35, 0.35) * step;
      const edge = rayToEdge(P, a);
      const r = rand(0.3, 0.62); // 안쪽 조각을 자르는 위치 (이웃 쐐기와 공유해야 틈이 안 생김)
      rays.push({ a, edge, mid: [P[0] + (edge[0] - P[0]) * r, P[1] + (edge[1] - P[1]) * r] });
    }
    // 각 꼭짓점의 P 기준 각도 (쐐기 사이에 낀 꼭짓점을 테두리에 포함하려고)
    const verts = HEX_POINTS.map((v) => ({ v, a: Math.atan2(v[1] - P[1], v[0] - P[0]) }));
    const pieces = [];
    for (let i = 0; i < n; i++) {
      const A = rays[i];
      const B = rays[(i + 1) % n];
      const a0 = A.a;
      let a1 = B.a;
      while (a1 <= a0) a1 += Math.PI * 2;
      const between = verts
        .map(({ v, a }) => { let x = a; while (x <= a0) x += Math.PI * 2; return { v, a: x }; })
