      pieces.forEach((poly) => {
        const c = poly.reduce((acc, p) => [acc[0] + p[0] / poly.length, acc[1] + p[1] / poly.length], [0, 0]);
        let dir = [c[0] - P[0], c[1] - P[1]];
        const len = Math.hypot(dir[0], dir[1]) || 1;
        dir = [dir[0] / len, dir[1] / len];
        const dust = poly.length === 3 && Math.abs(poly[0][0] - poly[1][0]) < 6;
        const dist = size * (dust ? rand(0.9, 1.4) : rand(0.35, 0.7) * (0.6 + len / 60));
