        shard.style.transformOrigin = \`\${c[0].toFixed(1)}% \${c[1].toFixed(1)}%\`;
        const light = Math.round(rand(200, 245));
        shard.style.background = \`linear-gradient(\${Math.round(rand(0, 360))}deg, rgb(\${light + 8}, \${light + 10}, 255), rgb(\${light - 70}, \${light - 50}, \${light - 30}))\`;
        shard.style.setProperty('--dx', \`\${(dir[0] * dist).toFixed(1)}px\`);
        shard.style.setProperty('--dy', \`\${(dir[1] * dist - rand(0, size * 0.15)).toFixed(1)}px\`);
        shard.style.setProperty('--fall', \`\${(size * rand(0.3, 0.7)).toFixed(1)}px\`);
        shard.style.setProperty('--r', \`\${Math.round(rand(-240, 240))}deg\`);
        shard.style.setProperty('--dur', \`\${rand(0.6, 0.95).toFixed(2)}s\`);
        playerEl.appendChild(shard);
      });
    }, 90);
  }

`+g.slice(end);
