const flow=\`  await ev(\\\"document.querySelector('#stageGrid .stage-btn').click()\\\");
  await sleep(2600);
  const tap = async (x, y) => {
    await send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x, y }] });
    await sleep(40);
    await send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  };
  const center = (sel) => ev('(() => { const r = document.querySelector(' + JSON.stringify(sel) + ').getBoundingClientRect(); return [r.left + r.width / 2, r.top + r.height / 2]; })()');
  // 1) 판 탭 → 추가 클릭이 나가는지
  await ev('window.__clicks = 0; document.addEventListener(\\\"click\\\", () => window.__clicks++, true); true');
  const [bx, by] = await center('#board .cell:nth-child(10)');
  await tap(bx, by); await sleep(300);
  console.log('  board tap → click events:', await ev('window.__clicks'), '(0 = 막힘)');
  // 2) 일시정지 창 뜨자마자 첫 버튼 탭 → 무시돼야 함
  const [px, py] = await center('#pauseBtn');
  await tap(px, py); await sleep(80);
  const [rx, ry] = await center('#modalButtons button');
  await tap(rx, ry); await sleep(150);
  console.log('  tap 0.1s after open → still paused:', await ev(\\\"!document.getElementById('modal').classList.contains('hidden')\\\"));
  await sleep(500);
  await tap(rx, ry); await sleep(300);
  console.log('  tap 0.7s after open → resumed:', await ev(\\\"document.getElementById('modal').classList.contains('hidden')\\\"));
\`;
