      if (!DICT[l]) return;
      lang = l;
      try { localStorage.setItem(LANG_KEY, l); } catch (e) { /* 이번 실행 동안만 */ }
      apply();
    },
  };
  // 스크립트는 body 끝에서 불러오므로 화면 요소가 이미 있음
  apply();
})();

