  // 탭: 탭한 칸 방향으로 한 칸 이동
  const SWIPE = 26;
  // 대각선으로 인정하는 각도 (수평에서 몇 도). 끌던 방향을 조금 더 유지해서 지그재그를 줄임
  //   처음 / 직선으로 끌던 중: 25°~65° (살짝 비스듬한 상하좌우 스와이프는 그대로 직선)
