// 효과음 (WebAudio 합성, 파일 없음)
// - window.Sound.create(isOn) → { step, blue, hit, crack, shatter, flatline, timeUp, tick, go, shuffle, clear, bump }
// - 단조롭지 않게: 음 두 개를 살짝 어긋나게 겹치기(detune), 잡음(유리·충격), 필터, 짧은 울림(echo),
//   걷는 소리는 매번 높이가 조금씩 다름, 파랑을 빠르게 이어 밟으면 음계가 올라감
(() => {
  let ctx = null;
  let master = null;
  let echoIn = null;
  let noiseBuf = null;
  const rand = (a, b) => a + Math.random() * (b - a);

  function init() {
    if (ctx) {
      if (ctx.state === 'suspended') ctx.resume();
      return true;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return false;
    ctx = new AC();
    // 출력: 전체 음량 → 압축(갑자기 커지는 소리 정리) → 스피커
    master = ctx.createGain();
    master.gain.value = 0.9;
    const comp = ctx.createDynamicsCompressor();
    master.connect(comp).connect(ctx.destination);
    // 짧은 울림: 0.11초 메아리가 조금씩 줄어들며 반복 (높은 소리는 깎아서 부드럽게)
    echoIn = ctx.createGain();
    const delay = ctx.createDelay();
    delay.delayTime.value = 0.11;
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 2600;
    const fb = ctx.createGain();
    fb.gain.value = 0.25;
    const wet = ctx.createGain();
    wet.gain.value = 0.2;
    echoIn.connect(delay);
    delay.connect(lp);
    lp.connect(fb);
    fb.connect(delay);
    lp.connect(wet);
    wet.connect(master);
    // 잡음 재료 (1초짜리 백색 잡음)
    noiseBuf = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
    const data = noiseBuf.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    return true;
  }

  // 소리 하나의 출구: 음량 모양(빠르게 커졌다 줄어듦) → 전체 + 울림
  function output(at, dur, vol, attack, echo) {
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, at);
    g.gain.exponentialRampToValueAtTime(vol, at + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, at + dur);
    g.connect(master);
    if (echo > 0) {
      const send = ctx.createGain();
      send.gain.value = echo;
      g.connect(send).connect(echoIn);
    }
    return g;
  }

  // 음: f(Hz), slide = 끝날 때 높이, detune = 두 번째 음을 몇 cent 어긋나게 겹칠지
  function tone({ f, dur = 0.1, type = 'triangle', vol = 0.06, delay = 0, attack = 0.005, slide, detune = 0, cutoff, echo = 0.2 }) {
    const at = ctx.currentTime + delay;
    let out = output(at, dur, vol, attack, echo);
    if (cutoff) {
      const filt = ctx.createBiquadFilter();
      filt.type = 'lowpass';
      filt.frequency.value = cutoff;
      filt.connect(out);
      out = filt;
    }
    (detune ? [0, detune] : [0]).forEach((cents) => {
      const osc = ctx.createOscillator();
      osc.type = type;
      osc.frequency.setValueAtTime(f, at);
      if (slide) osc.frequency.exponentialRampToValueAtTime(slide, at + dur);
      osc.detune.value = cents;
      osc.connect(out);
      osc.start(at);
      osc.stop(at + dur + 0.02);
    });
  }

  // 잡음: 필터로 깎아서 "퍽", "치익", "쨍그랑" 같은 질감
  function noise({ dur = 0.1, vol = 0.1, delay = 0, attack = 0.003, type = 'bandpass', freq = 2000, q = 1, sweepTo, echo = 0.15 }) {
    const at = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = noiseBuf;
    const filt = ctx.createBiquadFilter();
    filt.type = type;
    filt.frequency.setValueAtTime(freq, at);
    if (sweepTo) filt.frequency.exponentialRampToValueAtTime(sweepTo, at + dur);
    filt.Q.value = q;
    src.connect(filt).connect(output(at, dur, vol, attack, echo));
    src.start(at, Math.random() * 0.5);
    src.stop(at + dur + 0.02);
  }

  // 파랑 연속 밟기 음계 (도레미솔라 …): 1.6초 안에 이어 밟으면 한 칸씩 올라감
  const SCALE = [523, 587, 659, 784, 880, 1047, 1175, 1319, 1568, 1760, 2093];
  let combo = -1;
  let lastBlue = 0;

  const SOUNDS = {
    step() {
      tone({ f: rand(165, 205), dur: 0.05, type: 'triangle', vol: 0.05, echo: 0.05 });
      noise({ dur: 0.015, vol: 0.02, type: 'highpass', freq: 3000, echo: 0 });
    },
    bump() {
      tone({ f: 120, slide: 90, dur: 0.07, type: 'triangle', vol: 0.05, echo: 0 });
    },
    blue() {
      const now = performance.now();
      combo = now - lastBlue < 1600 ? Math.min(combo + 1, SCALE.length - 1) : 0;
      lastBlue = now;
      const f = SCALE[combo];
      tone({ f, dur: 0.16, type: 'sine', vol: 0.08, detune: 7, echo: 0.45 });
      tone({ f: f * 2, dur: 0.06, type: 'square', vol: 0.015, cutoff: 6000, echo: 0.3 });
      noise({ dur: 0.05, vol: 0.02, type: 'highpass', freq: 6000, echo: 0.2 });
    },
    hit() {
      noise({ dur: 0.18, vol: 0.28, type: 'lowpass', freq: 500, echo: 0.1 });            // 퍽
      tone({ f: 120, slide: 50, dur: 0.28, type: 'sine', vol: 0.22, echo: 0.1 });        // 둔한 울림
      noise({ dur: 0.08, vol: 0.1, delay: 0.02, type: 'bandpass', freq: 3500, q: 3 });   // 지직
    },
    crack() {
      // 유리에 금 가는 소리: 높은 "찌직" 두 번
      noise({ dur: 0.05, vol: 0.13, delay: 0.03, type: 'bandpass', freq: 4500, q: 8, echo: 0.3 });
      noise({ dur: 0.04, vol: 0.09, delay: 0.09, type: 'bandpass', freq: 5600, q: 10, echo: 0.3 });
      tone({ f: 2900, slide: 2100, dur: 0.05, type: 'square', vol: 0.02, delay: 0.03, cutoff: 7000 });
    },
    shatter() {
