    for (const n of names) { s[n](); await new Promise((r) => setTimeout(r, 60)); }
    for (let i = 0; i < 6; i++) s.blue(); // 연속 밟기 음계
    return names.join(', ') + ' | errors: ' + (window.__soundErr.length ? window.__soundErr.join('; ') : 'none');
  })()`);
  console.log(result);
  console.log('page errors:', errors.length ? errors : 'none');
} catch (e) { console.log('ERROR', e.message); } finally { ws?.close(); edge.kill(); }
EOF
