      noise({ dur: 0.05, vol: 0.09, delay: 0.03, type: 'bandpass', freq: 4500, q: 8, echo: 0.25 });
      noise({ dur: 0.04, vol: 0.06, delay: 0.09, type: 'bandpass', freq: 5200, q: 10, echo: 0.25 });
    },
    shatter() {
