    },
    timeUp() {
      // 시간 초과: 부드러운 "삐삐"
      [0, 0.26].forEach((delay) => tone({ f: 880, dur: 0.18, type: 'sine', vol: 0.09, delay, attack: 0.01, echo: 0.2 }));
