// stages.js 난이도 올리기: 파랑 추가 + 시간 + 빨강 속도 + 파랑 이동 주기. 같은 형식으로 다시 씀
const fs = require('fs');
const path = process.argv[2];
const src = fs.readFileSync(path, 'utf8');
const header = src.slice(0, src.indexOf('// ── 초급 (EASY) ──'));
const tiersTail = src.slice(src.indexOf('// 난이도 구간'));
eval(src.replace(/^const /gm, 'var '));

// 재현 가능한 난수 (스테이지마다 같은 결과)
function rng(seed) {
  let s = seed * 9301 + 49297;
  return () => { s = (s * 9301 + 49297) % 233280; return s / 233280; };
}
const W = 6, H = 8;
const round1 = (v) => Math.round(v * 10) / 10;
const round5 = (v) => Math.ceil(v / 5) * 5;

const RULES = {
  EASY: { addBlue: 3, shuffle: 4 },
  NORMAL: { addBlue: 4, shuffle: [2.5, 6] },
  HARD: { addBlue: 5, shuffle: [1.8, 4] },
};

function harden(st, tier, n) {
  const rule = RULES[tier];
  const rows = st.map.map((r) => r.split(''));
  let px, py;
  rows.forEach((r, y) => r.forEach((c, x) => { if (c === 'P') { px = x; py = y; } }));
  // 빈 칸 중 시작 위치 주변(1칸)과 빨강 시작 칸을 빼고 고르게 골라 파랑으로
  const hazardStarts = new Set(st.hazards.filter((h) => h.type !== 'sweep').map((h) => `${h.x},${h.y}`));
  const free = [];
  rows.forEach((r, y) => r.forEach((c, x) => {
    if (c === '.' && Math.max(Math.abs(x - px), Math.abs(y - py)) > 1 && !hazardStarts.has(`${x},${y}`)) free.push([x, y]);
  }));
  const rand = rng(n + 1);
  const picked = [];
  for (let k = 0; k < rule.addBlue && free.length; k++) {
    // 이미 고른 칸·기존 파랑과 가장 멀리 떨어진 후보 위주로 (뭉치지 않게)
    let best = null;
    let bestScore = -1;
    free.forEach(([x, y], i) => {
      let d = 99;
      rows.forEach((r, yy) => r.forEach((c, xx) => { if (c === 'B') d = Math.min(d, Math.abs(xx - x) + Math.abs(yy - y)); }));
      const score = d + rand() * 1.5;
      if (score > bestScore) { bestScore = score; best = i; }
    });
    const [x, y] = free.splice(best, 1)[0];
    rows[y][x] = 'B';
    picked.push([x, y]);
  }
  const added = picked.length;
  const out = { time: round5(st.time + added * 3), shuffle: rule.shuffle };
  out.map = rows.map((r) => r.join(''));
  if (st.blink) out.blink = { period: round1(st.blink.period * 0.9), warn: st.blink.warn };
  out.hazards = st.hazards.map((h) => {
    const f = h.type === 'chase' ? 1.1 : 1.15;
    return { ...h, speed: round1(h.speed * f) };
  });
  return { st: out, added };
}

const fmtHazard = (h) => {
  if (h.type === 'sweep') return `{ type: 'sweep', axis: '${h.axis}', pos: ${h.pos}, dir: ${h.dir}, speed: ${h.speed} }`;
  if (h.type === 'chase') return `{ type: 'chase', x: ${h.x}, y: ${h.y}, speed: ${h.speed} }`;
  return `{ type: 'bounce', x: ${h.x}, y: ${h.y}, dx: ${h.dx}, dy: ${h.dy}, speed: ${h.speed} }`;
};
const fmtStage = (s) => {
  const lines = ['  {', `    time: ${s.time},`, `    shuffle: ${JSON.stringify(s.shuffle).replace(/,/g, ', ')},`, '    map: ['];
  s.map.forEach((r) => lines.push(`      '${r}',`));
  lines.push('    ],');
  if (s.blink) lines.push(`    blink: { period: ${s.blink.period}, warn: ${s.blink.warn} },`);
  if (s.hazards.length) {
    lines.push('    hazards: [');
    s.hazards.forEach((h) => lines.push(`      ${fmtHazard(h)},`));
    lines.push('    ],');
  } else lines.push('    hazards: [],');
  lines.push('  },');
  return lines.join('\n');
};

const report = [];
const block = (name, title, list, offset) => {
  const res = list.map((st, i) => {
    const before = st.map.join('').split('B').length - 1;
    const { st: s, added } = harden(st, name, offset + i);
    report.push(`${name[0]}${i + 1}`.padEnd(4) + ` blue ${before}→${before + added}  time ${st.time}→${s.time}`);
    return fmtStage(s);
  });
  return `${title}\nconst ${name} = [\n${res.join('\n')}\n];\n`;
};
const out = header +
  block('EASY', '// ── 초급 (EASY): 파랑 이동 4초마다 ──', EASY, 0) + '\n' +
  block('NORMAL', '// ── 중급 (NORMAL): 빨강이 더 빠르고 많음, 파랑 이동 타이밍 랜덤 2.5~6초 ──', NORMAL, 12) + '\n' +
  block('HARD', '// ── 고급 (HARD): 빠른 빨강·추격자 여럿·가로세로 쓸기, 파랑 이동 타이밍 랜덤 1.8~4초 ──', HARD, 24) + '\n' +
  tiersTail;
fs.writeFileSync(path, out);
console.log(report.join('\n'));

