    </g>
    <!-- 몸통: 멀쩡한 티셔츠 / 너덜너덜한 티셔츠 -->
    <g class="h-torso">
      <rect x="12.5" y="21.5" width="14" height="13" rx="4.5" class="h-shirt"/>
      <path class="h-shirt-torn" d="M12.6 25.5 Q12.6 21.5 17 21.5 L22 21.5 Q26.5 21.5 26.5 25.5 L26.5 33 L25.2 31.6 L24.4 34.4 L23 32.3 L21.6 35 L20.4 32.4 L19 34.6 L17.8 32.2 L16.3 34.8 L15.2 32.5 L13.8 34.2 L12.6 32.4 Z"/>
      <ellipse cx="17" cy="27" rx="1.6" ry="1.2" class="h-hole"/>
      <ellipse cx="23" cy="29.5" rx="1.3" ry="1" class="h-hole"/>
      <ellipse cx="20.5" cy="24.5" rx="2.6" ry="1.3" class="h-soot-cloth"/>
    </g>
    <g class="h-leg h-leg-front">
      <rect x="15" y="33" width="4.2" height="9" rx="2" class="h-pants"/>
      <path class="h-pants-torn" d="M15 38 L15.8 40.6 L16.6 38.5 L17.5 41 L18.3 38.7 L19.2 40.3 L19.2 38 Z"/>
      <ellipse cx="18" cy="42.6" rx="3.2" ry="1.7" class="h-shoe"/>
    </g>
    <!-- 머리 -->
    <g class="h-head">
      <circle cx="20" cy="13" r="9.2" class="h-skin h-face"/>
      <path class="h-hair" d="M10.8 13.5 Q10.2 3.6 20 3.4 Q29.8 3.4 29.4 12.4 L27.4 8.6 L26.4 11.6 L24.2 7.6 L22.6 10.8 L20.6 6.8 L18.6 10.6 L16.6 7.2 L15.2 11 L13.2 8.2 L12.6 12.4 Z"/>
      <g class="h-bald">
        <ellipse cx="17.5" cy="6.6" rx="3.4" ry="1.5" class="h-shine"/>
        <circle cx="13.8" cy="9" r="0.6" class="h-stubble"/>
        <circle cx="16" cy="5.8" r="0.5" class="h-stubble"/>
        <circle cx="22.6" cy="5.4" r="0.6" class="h-stubble"/>
        <circle cx="25.6" cy="7.6" r="0.5" class="h-stubble"/>
        <circle cx="27.4" cy="10.2" r="0.6" class="h-stubble"/>
        <path d="M21 4.6 q2 1.6 4.6 1" class="h-burn-line"/>
      </g>
      <ellipse cx="15.6" cy="16.6" rx="2.2" ry="1.3" class="h-soot-face"/>
      <ellipse cx="25.6" cy="12" rx="1.6" ry="1.1" class="h-soot-face"/>
      <ellipse cx="22.6" cy="16" rx="1.8" ry="1.1" class="h-cheek"/>
      <g class="h-eyes">
        <ellipse cx="18.6" cy="12.6" rx="1.15" ry="1.5"/>
        <ellipse cx="24" cy="12.6" rx="1.15" ry="1.5"/>
      </g>
      <g class="h-eyes-x">
        <path d="M17.4 11.4 l2.4 2.4 M19.8 11.4 l-2.4 2.4 M22.8 11.4 l2.4 2.4 M25.2 11.4 l-2.4 2.4"/>
      </g>
      <path class="h-mouth" d="M20.4 17 Q22 18.4 23.6 17"/>
      <ellipse class="h-mouth-o" cx="22" cy="17.6" rx="1.2" ry="1.4"/>
    </g>
    <g class="h-arm h-arm-front">
      <rect x="20.5" y="23" width="3.6" height="9" rx="1.8" class="h-sleeve"/>
      <circle cx="22.3" cy="32.2" r="1.9" class="h-skin"/>
    </g>
  </g>
  <!-- 탄 연기 -->
  <g class="h-smoke">
    <circle cx="16" cy="6" r="2.4"/>
    <circle cx="21" cy="4" r="3"/>
    <circle cx="25" cy="7" r="2.2"/>
  </g>
</svg>`;

  const runTimers = new WeakMap();

  window.Hero = {
    mount(el) {
      if (!el.querySelector('.hero')) el.insertAdjacentHTML('afterbegin', SVG);
      el.dataset.hp = '3';
      el.dataset.face = 'right';
    },

    step(el, dx) {
      if (dx) el.dataset.face = dx < 0 ? 'left' : 'right'; // 위·아래로 갈 땐 보던 쪽 그대로
      el.classList.add('running');
      clearTimeout(runTimers.get(el));
      runTimers.set(el, setTimeout(() => el.classList.remove('running'), 260)); // 멈추면 서 있는 자세로
    },

    setHp(el, hp) {
      const v = String(Math.max(0, Math.min(3, hp)));
      if (el.dataset.hp !== v) el.dataset.hp = v;
    },

    hurt(el) {
      el.classList.remove('burn');
      void el.offsetWidth;
      el.classList.add('burn');
    },

    down(el) {
      el.classList.remove('running');
      el.classList.add('down');
    },

    reset(el) {
      el.classList.remove('down', 'burn', 'running');
      el.dataset.hp = '3';
    },
  };
})();

