  100% { filter: drop-shadow(0 0 3px rgba(45, 226, 255, 0.55)); }
}
@keyframes smoke {
  0% { opacity: 0.9; transform: translateY(0) scale(0.6); }
  100% { opacity: 0; transform: translateY(-10px) scale(1.5); }
}

