// 육각형 → 사람 캐릭터로 교체 (style.css, index.html, game.js, demo.js, sound.js)
const fs = require('fs');
process.chdir(process.argv[2]);
const patch = (p, rep) => {
  let s = fs.readFileSync(p, 'utf8');
  for (const [a, b] of rep) {
    if (s.split(a).length !== 2) throw new Error(p + ' miss ' + a.slice(0, 60));
    s = s.replace(a, () => b);
  }
  fs.writeFileSync(p, s);
};

// ── CSS: 육각형 블록 → 캐릭터 ──
let css = fs.readFileSync('style.css', 'utf8');
const a = css.indexOf('/* ── 육각형 플레이어 ──');
const b = css.indexOf('.countdown {');
if (a < 0 || b < 0) throw new Error('css markers');
const HERO_CSS = fs.readFileSync(process.argv[3], 'utf8');
css = css.slice(0, a) + HERO_CSS + '\n' + css.slice(b);
fs.writeFileSync('style.css', css);

// ── HTML ──
let h = fs.readFileSync('index.html', 'utf8');
const hexRe = /\n {10}<div class="hex">\n {12}<svg class="crack" viewBox="0 0 100 100" aria-hidden="true"><\/svg>\n {10}<\/div>\n {8}/g;
let n = 0;
h = h.replace(hexRe, () => { n++; return ''; });
if (n !== 2) throw new Error('html hex ' + n);
if (h.split('  <script src="crack.js"></script>').length !== 2) throw new Error('html crack script');
h = h.replace('  <script src="crack.js"></script>', '  <script src="hero.js"></script>');
fs.writeFileSync('index.html', h);

// ── 게임 ──
let g = fs.readFileSync('game.js', 'utf8');
const ga = g.indexOf('  // ── 육각형 금·깨짐 (모양 계산과 조각은 crack.js) ──');
const gb = g.indexOf('  // 막힌 방향으로 밀면');
if (ga < 0 || gb < 0) throw new Error('game markers');
g = g.slice(0, ga) + `  // ── 캐릭터 (그림과 동작은 hero.js) ──
  // 생명 0: 번쩍 하고 바닥에 털썩 쓰러짐
  function collapsePlayer() {
    sfx.sizzle();
    vibrate([30, 30, 120]);
    window.Hero.hurt(playerEl);
    setTimeout(() => {
      if (!state || state.phase !== 'breaking') return;
      window.Hero.down(playerEl);
      sfx.fall();
    }, 180);
  }

  // 판 시작·이어하기: 다시 일어선 모습으로 (모습은 render가 생명에 맞춰 바꿈)
  function restorePlayer() {
    window.Hero.reset(playerEl);
  }

` + g.slice(gb);
const gr = g.indexOf('  // 육각형 굴리기:');
const END = '  window.rollPlayer = rollPlayer; // 시연 화면에서도 같이 씀';
const ge = g.indexOf(END);
if (gr < 0 || ge < 0) throw new Error('roll markers');
g = g.slice(0, gr) + `  // 한 칸 이동: 그쪽을 보고 팔다리를 흔들며 뜀
  function stepPlayer(el, dx, dy) {
    window.Hero.step(el, dx, dy);
  }
  window.stepPlayer = stepPlayer; // 시연 화면에서도 같이 씀` + g.slice(ge + END.length);
