}

/* 막힌 방향으로 밀었을 때 살짝 툭 부딪힘 (--bx, --by = 민 방향) */
.player.bump { animation: bump 0.16s ease-out; }
@keyframes bump { 50% { translate: calc(var(--bx) * 12%) calc(var(--by) * 12%); } }

toolUseResult.content:
/* ── 플레이어 캐릭터 (hero.js) ──
   .player = 칸 이동 (translate). 이동과 같은 시간 동안 팔다리를 흔들며 뜀
   data-face = 보는 방향, data-hp = 남은 생명 (3 멀쩡 / 2 머리카락 탐 / 1 옷 너덜너덜 / 0 쓰러짐) */
.player {
  --move: 0.15s;
  --ease: cubic-bezier(0.25, 0.8, 0.35, 1);
  position: absolute;
  left: 0;
  top: 0;
  width: calc(100% / var(--cols));
  height: calc(100% / var(--rows));
  transition: transform var(--move) var(--ease);
  will-change: transform;
  pointer-events: none;
  z-index: 2;
}
.player.diag { --move: 0.19s; } /* 대각선은 거리가 길어서 조금 더 길게 */
.player .hero {
  position: absolute;
  left: 8%;
  top: 0;
  width: 84%;
  height: 100%;
  overflow: visible;
  filter: drop-shadow(0 0 3px rgba(45, 226, 255, 0.55));
}
.player[data-face="left"] .hero { transform: scaleX(-1); }
.player.invincible { animation: blink 0.15s infinite alternate; }

/* 색 */
.h-shadow { fill: rgba(0, 0, 0, 0.45); }
.h-skin { fill: #f6cfa6; stroke: #3b2a20; stroke-width: 0.7; }
.h-hair { fill: #3d2616; stroke: #24160c; stroke-width: 0.6; }
.h-shirt, .h-sleeve { fill: #2de2ff; stroke: #0b4f5c; stroke-width: 0.7; }
.h-sleeve.back { fill: #22b6cf; }
.h-pants { fill: #22325c; stroke: #0f1730; stroke-width: 0.6; }
.h-pants.back { fill: #1a2649; }
.h-shoe { fill: #1d1d24; }
.h-eyes ellipse { fill: #1b1410; }
.h-eyes-x path { stroke: #1b1410; stroke-width: 1.1; stroke-linecap: round; }
.h-mouth { fill: none; stroke: #5a2a1a; stroke-width: 0.8; stroke-linecap: round; }
.h-mouth-o { fill: #5a2a1a; }
.h-cheek { fill: rgba(255, 120, 120, 0.35); }
.h-shine { fill: rgba(255, 255, 255, 0.6); }
.h-stubble { fill: #3a2414; }
.h-burn-line { fill: none; stroke: #7a3a1a; stroke-width: 0.7; }
.h-soot-face { fill: rgba(40, 25, 15, 0.45); }
.h-shirt-torn { fill: #239fb4; stroke: #0b3a44; stroke-width: 0.7; }
.h-hole { fill: #2a1a10; }
.h-soot-cloth { fill: rgba(30, 20, 10, 0.5); }
.h-pants-torn { fill: #0b0f1d; }
.h-smoke { opacity: 0; transform-box: fill-box; transform-origin: center; }
.h-smoke circle { fill: rgba(160, 160, 170, 0.75); }

/* 생명 3: 멀쩡 (다친 모습은 숨김) */
.h-bald, .h-soot-face, .h-eyes-x, .h-mouth-o,
.h-shirt-torn, .h-hole, .h-soot-cloth, .h-pants-torn { display: none; }
/* 생명 2 이하: 머리카락이 타서 대머리 + 얼굴 검댕 + 놀란 입 */
.player:is([data-hp="2"], [data-hp="1"], [data-hp="0"]) :is(.h-hair, .h-cheek, .h-mouth) { display: none; }
.player:is([data-hp="2"], [data-hp="1"], [data-hp="0"]) :is(.h-bald, .h-soot-face, .h-mouth-o) { display: inline; }
/* 생명 1 이하: 옷이 너덜너덜 (찢어진 밑단, 탄 구멍, 검댕, 찢어진 바지) */
.player:is([data-hp="1"], [data-hp="0"]) .h-shirt { display: none; }
.player:is([data-hp="1"], [data-hp="0"]) :is(.h-shirt-torn, .h-hole, .h-soot-cloth, .h-pants-torn) { display: inline; }
.player:is([data-hp="1"], [data-hp="0"]) .h-sleeve { fill: #239fb4; }
.player:is([data-hp="1"], [data-hp="0"]) .h-sleeve.back { fill: #1b8597; }

/* 달리기: 팔다리를 엉덩이·어깨 기준으로 번갈아 흔들고 머리가 살짝 들썩 */
.h-leg, .h-arm { transform-box: fill-box; transform-origin: 50% 0%; }
.h-head { transform-box: fill-box; transform-origin: 50% 100%; }
.h-body { transform-box: view-box; transform-origin: 20px 44px; transition: transform 0.35s cubic-bezier(0.5, 0, 0.7, 1); }
.player.running .h-leg-front { animation: swing 0.28s ease-in-out infinite alternate; }
.player.running .h-leg-back { animation: swing 0.28s ease-in-out infinite alternate-reverse; }
.player.running .h-arm-front { animation: swing-arm 0.28s ease-in-out infinite alternate-reverse; }
.player.running .h-arm-back { animation: swing-arm 0.28s ease-in-out infinite alternate; }
.player.running .h-head { animation: bob 0.14s ease-in-out infinite alternate; }
/* 가만히 있을 때: 숨쉬듯 머리가 살짝 */
.player:not(.running):not(.down) .h-head { animation: idle 1.6s ease-in-out infinite; }

/* 빨강에 닿음: 주황빛으로 번쩍 + 연기 */
.player.burn .hero { animation: burn 0.5s ease-out; }
.player.burn .h-smoke { animation: smoke 0.9s ease-out; }
/* 생명 0: 바닥에 털썩 쓰러짐 (발 기준으로 옆으로 눕고 눈은 ××, 연기 계속) */
.player.down { animation: none; }
.player.down .h-body { transform: rotate(-88deg); }
.player.down .h-eyes { display: none; }
.player.down .h-eyes-x { display: inline; }
.player.down .h-smoke { animation: smoke 1.3s ease-out 0.3s infinite; }

@keyframes swing { from { transform: rotate(-30deg); } to { transform: rotate(30deg); } }
@keyframes swing-arm { from { transform: rotate(-40deg); } to { transform: rotate(40deg); } }
@keyframes bob { from { transform: translateY(0); } to { transform: translateY(-1.2px); } }
@keyframes idle { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(0.5px); } }
@keyframes burn {
  0% { filter: brightness(1.8) sepia(1) saturate(5) hue-rotate(-25deg) drop-shadow(0 0 7px #ff7a1a); }
  100% { filter: drop-shadow(0 0 3px rgba(45, 226, 255, 0.55)); }
}
@keyframes smoke {
  0% { opacity: 0.9; transform: translateY(0) scale(0.6); }
  100% { opacity: 0; transform: translateY(-10px) scale(1.5); }
}

/* 막힌 방향으로 밀었을 때 살짝 툭 부딪힘 (--bx, --by = 민 방향) */
.player.bump { animation: bump 0.16s ease-out; }
@keyframes bump { 50% { translate: calc(var(--bx) * 12%) calc(var(--by) * 12%); } }

