          <path class="h-brow" d="M25.1 6.7 q0.7 -0.3 1.2 0.1"/>
        </g>
        <!-- 대머리 (생명 2 이하): 탄 두피, 그루터기, 그을음 -->
        <g class="h-bald">
          <path d="M15.7 9.6 Q15.2 3.6 20.8 2.9 Q25.6 2.6 26.6 6.6 Q24 5.6 21 5.8 Q18 6.2 17.2 10.4 Z" fill="url(#ID-scalp)" class="h-scalp"/>
          <ellipse cx="20.2" cy="4.4" rx="2.2" ry="0.9" class="h-shine"/>
