            <circle cx="24.6" cy="4.4" r="0.3"/><circle cx="16.2" cy="8.4" r="0.35"/><circle cx="25.6" cy="5.8" r="0.3"/>
          </g>
          <path class="h-singe" d="M21.6 3.4 q1.6 0.8 3.4 0.4 M16.6 5.6 q0.6 1.2 0.4 2.4"/>
          <ellipse cx="23.6" cy="10.8" rx="1.6" ry="0.9" class="h-soot-face"/>
          <ellipse cx="19.8" cy="5.8" rx="1.8" ry="0.8" class="h-soot-face"/>
        </g>
        <!-- 눈 (깜빡임은 style.css) -->
        <g class="h-eyes">
          <ellipse cx="23.1" cy="8.4" rx="0.85" ry="1.05" class="h-sclera"/>
          <ellipse cx="23.4" cy="8.5" rx="0.55" ry="0.75" class="h-iris"/>
          <circle cx="23.55" cy="8.2" r="0.18" class="h-glint"/>
          <ellipse cx="25.6" cy="8.3" rx="0.6" ry="0.95" class="h-sclera"/>
          <ellipse cx="25.8" cy="8.4" rx="0.4" ry="0.68" class="h-iris"/>
        </g>
        <g class="h-eyes-x">
          <path d="M22.3 7.6 l1.6 1.6 M23.9 7.6 l-1.6 1.6 M25 7.6 l1.3 1.4 M26.3 7.6 l-1.3 1.4"/>
        </g>
        <path class="h-mouth" d="M23.4 11.7 Q24.5 12.4 25.5 11.6"/>
        <ellipse class="h-mouth-o" cx="24.5" cy="12" rx="0.7" ry="0.85"/>
        <ellipse class="h-cheek" cx="24.4" cy="10.4" rx="1.1" ry="0.6"/>
      </g>
      ${arm('front')}
    </g>
    ${leg('front')}
  </g>
  <!-- 탄 연기 -->
  <g class="h-smoke">
    <circle cx="18" cy="3" r="2.2"/>
    <circle cx="22" cy="1.2" r="2.8"/>
    <circle cx="25.4" cy="3.6" r="2"/>
  </g>
</svg>`;

  const runTimers = new WeakMap();

  window.Hero = {
    mount(el) {
      if (el.querySelector('.hero')) return;
      const id = el.id || `hero${Math.random().toString(36).slice(2, 7)}`;
      el.insertAdjacentHTML('afterbegin', SVG.replace(/ID-/g, `${id}-`));
      // 그라데이션 연결 (id를 쓰는 곳만)
      el.style.setProperty('--g-skin', `url(#${id}-skin)`);
      el.style.setProperty('--g-shirt', `url(#${id}-shirt)`);
      el.style.setProperty('--g-jeans', `url(#${id}-jeans)`);
      el.style.setProperty('--g-hair', `url(#${id}-hair)`);
      el.dataset.hp = '3';
      el.dataset.face = 'right';
    },

    step(el, dx) {
      if (dx) el.dataset.face = dx < 0 ? 'left' : 'right'; // 위·아래로 갈 땐 보던 쪽 그대로
      el.classList.add('running');
      clearTimeout(runTimers.get(el));
      runTimers.set(el, setTimeout(() => el.classList.remove('running'), 280)); // 멈추면 서 있는 자세로
    },

    setHp(el, hp) {
      const v = String(Math.max(0, Math.min(3, hp)));
      if (el.dataset.hp !== v) el.dataset.hp = v;
    },

    hurt(el) {
      el.classList.remove('burn');
      void el.offsetWidth;
      el.classList.add('burn');
    },

    down(el) {
      el.classList.remove('running');
      el.classList.add('down');
    },

    reset(el) {
      el.classList.remove('down', 'burn', 'running');
      el.dataset.hp = '3';
    },
  };
})();

