.h-mouth { fill: none; stroke: #8a3c2a; stroke-width: 0.4; stroke-linecap: round; }
.h-mouth-o { fill: #6a2a1c; }
.h-cheek { fill: rgba(255, 120, 110, 0.28); }
.h-shirt, .h-sleeve, .h-sleeve-torn { fill: var(--g-shirt); stroke: #0b4f5c; stroke-width: 0.4; }
.h-sleeve.back, .h-sleeve-torn.back { filter: brightness(0.8); }
.h-shirt-shade { fill: rgba(0, 40, 60, 0.18); }
.h-collar { fill: none; stroke: #0b6274; stroke-width: 0.6; stroke-linecap: round; }
.h-belt { fill: #4a2c16; }
.h-buckle { fill: #c9b27a; stroke: #6d5a2c; stroke-width: 0.25; }
.h-jeans { fill: var(--g-jeans); stroke: #0f1730; stroke-width: 0.35; }
.h-jeans.back { filter: brightness(0.78); }
.h-shoe { fill: #2a2d36; stroke: #111318; stroke-width: 0.3; }
.h-shoe.back { fill: #1f2129; }
.h-sole { stroke: #e9ecf3; stroke-width: 0.6; }
.h-scalp { stroke: #8a4a2a; stroke-width: 0.35; }
.h-shine { fill: rgba(255, 255, 255, 0.55); }
.h-stubble circle { fill: #2d1a0e; }
.h-singe { fill: none; stroke: #6a2c10; stroke-width: 0.45; stroke-linecap: round; }
.h-soot-face { fill: rgba(40, 24, 14, 0.4); }
.h-shirt-torn { fill: var(--g-shirt); stroke: #0b3a44; stroke-width: 0.4; filter: brightness(0.82) saturate(0.85); }
.h-hole { fill: #23160d; stroke: #d9752a; stroke-width: 0.35; } /* 탄 구멍: 가장자리가 그을린 주황 */
.h-soot { fill: rgba(30, 18, 10, 0.4); }
.h-rip { fill: var(--g-skin); stroke: #0f1730; stroke-width: 0.3; }
.h-smoke { opacity: 0; transform-box: fill-box; transform-origin: center; }
.h-smoke circle { fill: rgba(170, 170, 180, 0.7); }

/* ── 생명별 모습 ── */
.h-bald, .h-eyes-x, .h-mouth-o, .h-shirt-torn, .h-sleeve-torn, .h-burn-holes, .h-rip { display: none; }
/* 생명 2 이하: 머리카락이 타서 대머리 + 그을음 + 놀란 입 */
.player:is([data-hp="2"], [data-hp="1"], [data-hp="0"]) :is(.h-hair, .h-cheek, .h-mouth) { display: none; }
.player:is([data-hp="2"], [data-hp="1"], [data-hp="0"]) :is(.h-bald, .h-mouth-o) { display: inline; }
/* 생명 1 이하: 옷이 너덜너덜 (찢어진 밑단·소매, 탄 구멍, 그을음, 찢어진 청바지) */
.player:is([data-hp="1"], [data-hp="0"]) :is(.h-shirt, .h-shirt-shade, .h-sleeve) { display: none; }
.player:is([data-hp="1"], [data-hp="0"]) :is(.h-shirt-torn, .h-sleeve-torn, .h-burn-holes, .h-rip) { display: inline; }

/* ── 관절 기준점 ── */
.h-body, .h-torso, .h-head, .h-thigh, .h-shin, .h-foot, .h-uarm, .h-farm { transform-box: view-box; }
.h-body { transform-origin: 21px 55px; }
.h-torso { transform-origin: 20.5px 31.5px; transition: transform 0.2s ease-out; }
.h-head { transform-origin: 20.8px 15.2px; }
.h-thigh { transform-origin: 20.5px 31.5px; }
.h-shin { transform-origin: 20.5px 41.6px; }
.h-foot { transform-origin: 20.5px 52px; }
.h-uarm { transform-origin: 20.6px 17.6px; }
.h-farm { transform-origin: 20.6px 25px; }

/* ── 가만히 서 있기: 숨쉬기 + 가끔 눈 깜빡임 + 팔이 살짝 ── */
.h-uarm.front { transform: rotate(-4deg); }
.h-uarm.back { transform: rotate(5deg); }
.h-farm { transform: rotate(-12deg); }
.player:not(.running):not(.down) .h-torso { animation: breathe 2.6s ease-in-out infinite; }
.h-eyes { transform-box: fill-box; transform-origin: center; animation: blink-eye 4.2s infinite; }

/* ── 달리기: 4단계 (착지 → 낮춤 → 다리 교차 → 차고 나감). 뒤쪽 팔다리는 반 박자 늦게 ── */
.player.running .h-torso { transform: rotate(8deg); }                 /* 상체를 앞으로 */
.player.running .h-head { transform: rotate(-5deg); }                 /* 시선은 앞으로 */
.player.running .h-body { animation: run-bob calc(var(--run) / 2) ease-in-out infinite; }
.player.running .h-thigh { animation: run-thigh var(--run) linear infinite; }
.player.running .h-shin { animation: run-shin var(--run) linear infinite; }
.player.running .h-foot { animation: run-foot var(--run) linear infinite; }
.player.running .h-uarm { animation: run-uarm var(--run) ease-in-out infinite; }
.player.running .h-farm { animation: run-farm var(--run) ease-in-out infinite; }
.player.running :is(.h-thigh, .h-shin, .h-foot, .h-uarm, .h-farm).back { animation-delay: calc(var(--run) / -2); }

/* ── 빨강에 닿음: 뒤로 움찔 + 주황빛 번쩍 + 연기 ── */
.player.burn .hero { animation: burn 0.5s ease-out; }
.player.burn .h-body { animation: flinch 0.4s ease-out; }
.player.burn .h-smoke { animation: smoke 0.9s ease-out; }

/* ── 생명 0: 무릎이 꺾이고 뒤로 털썩 → 누워서 연기 ── */
.player.down { animation: none; }
.player.down .h-body { animation: collapse 0.6s cubic-bezier(0.5, 0, 0.75, 1) forwards; }
.player.down .h-thigh { transform: rotate(-18deg); transition: transform 0.3s; }
.player.down .h-shin { transform: rotate(34deg); transition: transform 0.3s; }
.player.down .h-uarm.front { transform: rotate(-150deg); transition: transform 0.4s; }
.player.down .h-uarm.back { transform: rotate(-120deg); transition: transform 0.4s; }
.player.down .h-eyes { display: none; }
.player.down .h-eyes-x { display: inline; }
.player.down .h-smoke { animation: smoke-down 1.3s ease-out 0.5s infinite; }

@keyframes breathe { 0%, 100% { transform: scale(1, 1); } 50% { transform: scale(1.01, 1.018); } }
@keyframes blink-eye { 0%, 93%, 100% { transform: scaleY(1); } 95% { transform: scaleY(0.1); } }
@keyframes run-bob {
  0% { transform: translateY(0.6px); }          /* 착지하며 낮아짐 */
  50% { transform: translateY(-1.6px); }        /* 차고 나가며 떠오름 */
  100% { transform: translateY(0.6px); }
}
/* 허벅지: 음수 = 앞으로, 양수 = 뒤로 */
@keyframes run-thigh {
  0% { transform: rotate(-32deg); }
  25% { transform: rotate(-12deg); }
  50% { transform: rotate(28deg); }
  75% { transform: rotate(4deg); }
  100% { transform: rotate(-32deg); }
}
/* 무릎: 양수 = 접힘 (뒤로 차올린 다리를 끌어올릴 때 크게) */
@keyframes run-shin {
  0% { transform: rotate(10deg); }
  22% { transform: rotate(24deg); }
  45% { transform: rotate(16deg); }
  62% { transform: rotate(92deg); }
  82% { transform: rotate(70deg); }
  100% { transform: rotate(10deg); }
}
@keyframes run-foot {
  0% { transform: rotate(-10deg); }
  40% { transform: rotate(8deg); }
  55% { transform: rotate(32deg); }
  80% { transform: rotate(-4deg); }
  100% { transform: rotate(-10deg); }
}
/* 팔: 같은 쪽 다리와 반대로 흔들고 팔꿈치는 굽힘 */
@keyframes run-uarm { 0%, 100% { transform: rotate(38deg); } 50% { transform: rotate(-42deg); } }
@keyframes run-farm { 0%, 100% { transform: rotate(-58deg); } 50% { transform: rotate(-98deg); } }
@keyframes flinch {
  0% { transform: none; }
  25% { transform: translate(-2.2px, -1.2px) rotate(-9deg); }
  100% { transform: none; }
}
/* 쓰러짐: 무릎이 꺾이며 주저앉고 → 발 기준으로 뒤로 넘어가 칸 안에 눕기 */
@keyframes collapse {
  0% { transform: none; }
  35% { transform: translateY(3px) rotate(6deg) scale(0.96, 0.9); }
  100% { transform: translate(20px, -5px) rotate(-90deg) scale(0.78); }
}
@keyframes burn {
  0% { filter: brightness(1.8) sepia(1) saturate(5) hue-rotate(-25deg) drop-shadow(0 0 7px #ff7a1a); }
  100% { filter: drop-shadow(0 0 2.5px rgba(45, 226, 255, 0.5)); }
}
@keyframes smoke {
  0% { opacity: 0.85; transform: translateY(0) scale(0.6); }
  100% { opacity: 0; transform: translateY(-10px) scale(1.5); }
}
@keyframes smoke-down {
  0% { opacity: 0.85; transform: translate(-6px, 36px) scale(0.6); }
  100% { opacity: 0; transform: translate(-6px, 25px) scale(1.5); }
}

/* 막힌 방향으로 밀었을 때 살짝 툭 부딪힘 (--bx, --by = 민 방향) */
.player.bump { animation: bump 0.16s ease-out; }
@keyframes bump { 50% { translate: calc(var(--bx) * 12%) calc(var(--by) * 12%); } }

