// 판 회전·뒤집기 (중급 회전, 고급 뒤집기, 특급 둘 다)
const fs = require('fs');
process.chdir(process.argv[2]);
const patch = (p, rep) => {
  let s = fs.readFileSync(p, 'utf8');
  for (const [a, b] of rep) {
    if (s.split(a).length !== 2) throw new Error(p + ' miss ' + a.slice(0, 60));
    s = s.replace(a, () => b);
  }
  fs.writeFileSync(p, s);
};

// ── 스테이지 데이터: 난이도별 판 바뀜 설정 ──
patch('stages.js', [
  [`const TIERS = [
  { name: 'EASY', stages: EASY },
  { name: 'NORMAL', stages: NORMAL },
  { name: 'HARD', stages: HARD },
  { name: 'EXPERT', stages: EXPERT },
];`,
  `// twist: 판이 바뀌는 방식 (kinds 중 하나를 랜덤으로, every = [최소, 최대] 초 사이 랜덤 간격)
//   spin = 지진처럼 흔들린 뒤 시계 방향 180° 회전 (모든 것이 180° 돌아간 자리로)
//   flip = 왼쪽/오른쪽(랜덤)으로 뒤집혀 뒷면이 앞으로 (좌우가 바뀜). 뒷면이면 불빛이 흐려지고, 다시 뒤집히면 밝아짐
const TIERS = [
  { name: 'EASY', stages: EASY },
  { name: 'NORMAL', stages: NORMAL, twist: { kinds: ['spin'], every: [5, 20] } },
  { name: 'HARD', stages: HARD, twist: { kinds: ['flip'], every: [5, 20] } },
  { name: 'EXPERT', stages: EXPERT, twist: { kinds: ['spin', 'flip'], every: [5, 20] } },
];`],
]);

// ── 게임 ──
patch('game.js', [
  // 상태
  [`      shuffleLeft: nextShuffleTime(def.shuffle ?? BLUE_SHUFFLE_TIME), // 파랑이 옮겨지기까지 남은 시간
    };`,
  `      shuffleLeft: nextShuffleTime(def.shuffle ?? BLUE_SHUFFLE_TIME), // 파랑이 옮겨지기까지 남은 시간
      twist: TIERS[tierOf(n).tier].twist || null,  // 판 회전·뒤집기 (초급은 없음)
      flips: 0,                                    // 뒤집힌 횟수 (홀수 = 뒷면 → 불빛 흐림)
    };
    state.twistLeft = state.twist ? twistDelay(state.twist) : 0;
    stopTwist();`],
  // 루프: 시간이 되면 판 바뀜
  [`      if (state.drag) {
        state.drag.acc += dt;
        if (state.drag.acc >= DRAG_STEP) { state.drag.acc = 0; dragStep(); }
      }`,
  `      if (state.drag) {
        state.drag.acc += dt;
        if (state.drag.acc >= DRAG_STEP) { state.drag.acc = 0; dragStep(); }
      }
      if (state.twist) {
        state.twistLeft -= dt;
        if (state.twistLeft <= 0) startTwist();
      }`],
  // 판이 바뀌는 동안에도 화면은 계속 그림 (시간·빨강은 멈춤)
  [`    if (state.phase === 'ready' || state.phase === 'play') rafId = requestAnimationFrame(loop);`,
   `    if (state.phase === 'ready' || state.phase === 'play' || state.phase === 'twist') rafId = requestAnimationFrame(loop);`],
  // 스테이지 화면으로 나가면 정리
  [`  function showStages() {
    stopCelebration();`,
   `  function showStages() {
    stopCelebration();
    stopTwist();`],
  // 본체
  [`  // ── 클리어 연출:`,
  `  // ── 판 회전·뒤집기 (중급·고급·특급) ──
  // 화면에서 판을 실제로 돌리거나 뒤집은 뒤, 같은 순간에 모든 위치를 돌아간 자리로 옮기고 판 모양은 원래대로 되돌림
  // → 눈에는 끊김 없이 이어지고, 게임 판정은 늘 반듯한 판 기준. 바뀌는 동안은 시간·빨강·입력이 멈춤
  const twistDelay = (tw) => tw.every[0] + Math.random() * (tw.every[1] - tw.every[0]);

  // 위치 옮기기. spin: (x, y) → (오른쪽 끝 - x, 아래 끝 - y), flip: (x, y) → (오른쪽 끝 - x, y)
  function remapBoard(kind) {
    const spin = kind === 'spin';
    const mx = (x) => COLS - 1 - x;
    const my = (y) => (spin ? ROWS - 1 - y : y);
    const mi = (i) => idx(mx(i % COLS), my(Math.floor(i / COLS)));
    const tiles = new Array(state.tiles.length);
    state.tiles.forEach((t, i) => { tiles[mi(i)] = t; });
    state.tiles = tiles;
    state.pops = new Set([...state.pops].map(mi));
    state.px = mx(state.px);
    state.py = my(state.py);
    if (state.drag) { state.drag.tx = mx(state.drag.tx); state.drag.ty = my(state.drag.ty); }
    state.hazards.forEach((h) => {
      if (h.type === 'sweep') {
        if (h.axis === 'col') { h.pos = mx(h.pos); h.dir = -h.dir; }
        else if (spin) { h.pos = my(h.pos); h.dir = -h.dir; }
        return;
      }
      h.x = mx(h.x);
      h.y = my(h.y);
      if (h.type === 'bounce') { h.dx = -h.dx; if (spin) h.dy = -h.dy; }
    });
    // 육각형도 화면에서 보이던 모습 그대로 (회전은 +180°, 뒤집기는 좌우 반전)
    if (spin) playerEl.rot = (playerEl.rot || 0) + 180;
    else { playerEl.rot = -(playerEl.rot || 0); playerEl.fx = -(playerEl.fx || 1); }
    playerEl.style.setProperty('--rot', \`\${playerEl.rot}deg\`);
    playerEl.style.setProperty('--fx', playerEl.fx || 1);
  }

  let twistAnims = [];
  async function startTwist() {
    const st = state;
    st.phase = 'twist';
    const kind = st.twist.kinds[Math.floor(Math.random() * st.twist.kinds.length)];
    const alive = () => state === st && st.phase === 'twist';
    const run = async (keyframes, opts) => {
      const a = board.animate(keyframes, opts);
      twistAnims.push(a);
      try { await a.finished; } catch (e) { return null; } // 취소됨
      return a;
    };
    countdownEl.textContent = kind === 'spin' ? '↻' : '⇄';
    countdownEl.classList.remove('hidden');
    let a;
    if (kind === 'spin') {
      // 지진처럼 흔들림 → 시계 방향 180°
      sfx.quake();
      vibrate([40, 30, 40, 30, 70]);
      const q = [];
      for (let k = 0; k <= 12; k++) {
        const s = k === 0 || k === 12 ? 0 : 1 - k / 14;
        q.push({ transform: \`translate(\${((k % 2 ? 1 : -1) * 6 * s).toFixed(1)}px, \${((k % 3) - 1) * 3 * s}px) rotate(\${((k % 2 ? -1 : 1) * 1.2 * s).toFixed(2)}deg)\` });
      }
      if (!(await run(q, { duration: 800, easing: 'linear' })) || !alive()) return;
      countdownEl.classList.add('hidden');
      sfx.spin();
      a = await run([{ transform: 'rotate(0deg)' }, { transform: 'rotate(180deg)' }],
        { duration: 900, easing: 'cubic-bezier(0.6, 0, 0.35, 1)', fill: 'forwards' });
    } else {
      // 왼쪽 또는 오른쪽으로 뒤집기 (뒷면이 앞으로)
      const dir = Math.random() < 0.5 ? -1 : 1;
      sfx.flip();
      setTimeout(() => countdownEl.classList.add('hidden'), 350);
      a = await run([{ transform: 'perspective(900px) rotateY(0deg)' }, { transform: \`perspective(900px) rotateY(\${dir * 180}deg)\` }],
        { duration: 900, easing: 'cubic-bezier(0.6, 0, 0.35, 1)', fill: 'forwards' });
    }
    if (!a || !alive()) return;
    // 같은 순간에: 위치를 돌아간 자리로 → 다시 그림(전환 효과 없이) → 판 모양 원래대로
    remapBoard(kind);
    board.classList.add('snap');
    playerEl.classList.add('snap');
    cellClass.fill('');
    render();
    a.cancel();
    twistAnims = [];
    requestAnimationFrame(() => { board.classList.remove('snap'); playerEl.classList.remove('snap'); });
    if (kind === 'flip') {
      st.flips++;
      const back = st.flips % 2 === 1; // 뒷면 = 불빛 흐림, 다시 앞면(360°) = 밝아짐
      setTimeout(() => { if (state === st) board.classList.toggle('dim', back); }, 30);
      (back ? sfx.dim : sfx.bright)();
    }
    st.phase = 'play';
    st.twistLeft = twistDelay(st.twist);
    lastTime = performance.now();
  }

  function stopTwist() {
    twistAnims.forEach((a) => a.cancel());
    twistAnims = [];
    board.classList.remove('dim', 'snap');
    playerEl.classList.remove('snap');
    countdownEl.classList.add('hidden');
  }

  // ── 클리어 연출:`],
]);

// ── 스타일 ──
let c = fs.readFileSync('style.css', 'utf8');
const r1 = `  transform: rotate(var(--rot, 0deg));
  transition: transform var(--move) var(--ease);
  will-change: transform;
}`;
if (c.split(r1).length !== 2) throw new Error('hex css');
c = c.replace(r1, () => `  transform: rotate(var(--rot, 0deg)) scaleX(var(--fx, 1)); /* --fx: 판이 뒤집히면 좌우 반전 */
  transition: transform var(--move) var(--ease);
  will-change: transform;
}`);
const r2 = '.board.shake { animation: shake 0.3s; }';
if (c.split(r2).length !== 2) throw new Error('board css');
c = c.replace(r2, () => r2 + `
/* 판 회전·뒤집기 직후 한 순간은 전환 효과 없이 (돌아간 자리로 옮긴 게 미끄러져 보이지 않게) */
.board.snap .cell::before, .player.snap, .player.snap .hex { transition: none !important; }
/* 뒷면(뒤집힌 상태): 바닥 불빛이 전체적으로 흐려짐 */
.cell::before { transition: background 0.08s, box-shadow 0.08s, filter 0.6s; }
.board.dim .cell::before { filter: brightness(0.38) saturate(0.7); }`);
fs.writeFileSync('style.css', c);

// ── 효과음 ──
patch('sound.js', [[`    wave() {`, `    quake() {
      // 지진: 낮게 우르르 + 덜컹
      noise({ dur: 0.85, vol: 0.22, type: 'lowpass', freq: 160, echo: 0.1 });
      tone({ f: 46, slide: 38, dur: 0.85, type: 'sine', vol: 0.18, attack: 0.05, echo: 0 });
      [0.15, 0.4, 0.62].forEach((delay) => noise({ dur: 0.08, vol: 0.12, delay, type: 'lowpass', freq: 300, echo: 0 }));
    },
    spin() {
      // 회전: 묵직하게 "휘이잉"
      noise({ dur: 0.9, vol: 0.09, type: 'bandpass', freq: 250, sweepTo: 1400, q: 1.2, echo: 0.3 });
      tone({ f: 150, slide: 300, dur: 0.9, type: 'sine', vol: 0.05, attack: 0.1, echo: 0.2 });
    },
    flip() {
      // 뒤집기: 가볍게 "휙"
      noise({ dur: 0.7, vol: 0.1, type: 'bandpass', freq: 600, sweepTo: 3000, q: 1.5, echo: 0.3 });
    },
    dim() {
      // 불빛이 흐려짐: 내려가는 음
      tone({ f: 660, slide: 330, dur: 0.6, type: 'sine', vol: 0.05, attack: 0.02, echo: 0.4 });
    },
    bright() {
      // 다시 밝아짐: 올라가는 실로폰 음
      [523, 784, 1047].forEach((f, i) => bell(f, { vol: 0.05, dur: 0.5, delay: i * 0.08, echo: 0.4 }));
    },
    wave() {`]]);
console.log('ok');

