  m.forEach((r, y) => [...r].forEach((c, x) => { if (c === 'P') { px = x; py = y; } }));
  const walk = (x, y) => x >= 0 && x < W && y >= 0 && y < H && m[y][x] !== '#' && m[y][x] !== 'G';
  const starts = st.hazards.filter((h) => h.type !== 'sweep').map((h) => [h.x, h.y]);
  const sweepRows = st.hazards.filter((h) => h.type === 'sweep' && h.axis === 'row').map((h) => h.pos);
  const added = [];
  for (let k = 0; k < 2; k++) {
    let best = null, bestScore = -1;
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      if (!walk(x, y) || Math.max(Math.abs(x - px), Math.abs(y - py)) <= 2 || sweepRows.includes(y)) continue;
      // 기존 빨강과 멀수록, 가운데 줄일수록 좋게
      const d = Math.min(99, ...starts.concat(added.map((h) => [h.x, h.y])).map(([sx, sy]) => Math.abs(sx - x) + Math.abs(sy - y)));
      const score = d * 10 - Math.abs(y - 3.5) + ((x * 7 + y * 3 + n) % 5) * 0.1;
      if (score > bestScore) { bestScore = score; best = [x, y]; }
    }
    if (!best) break;
    const [x, y] = best;
    // 가로로 움직일 칸이 넉넉하면 가로, 아니면 세로 (번갈아)
    let run = 0;
    for (let xx = 0; xx < W; xx++) if (walk(xx, y)) run++;
    const horizontal = (k === 0 ? run >= 4 : run < 4 || !walk(x, y + 1) && !walk(x, y - 1)) && (walk(x + 1, y) || walk(x - 1, y));
    const dx = horizontal ? (walk(x + 1, y) ? 1 : -1) : 0;
    const dy = horizontal ? 0 : (walk(x, y + 1) ? 1 : -1);
    added.push({ type: 'bounce', x, y, dx, dy, speed: round1(2 + n * 0.05) });
    starts.push([x, y]);
  }
  return { ...st, hazards: [...st.hazards, ...added] };
}

const fmtHazard = (h) => {
  if (h.type === 'sweep') return `{ type: 'sweep', axis: '${h.axis}', pos: ${h.pos}, dir: ${h.dir}, speed: ${h.speed} }`;
  if (h.type === 'chase') return `{ type: 'chase', x: ${h.x}, y: ${h.y}, speed: ${h.speed} }`;
  return `{ type: 'bounce', x: ${h.x}, y: ${h.y}, dx: ${h.dx}, dy: ${h.dy}, speed: ${h.speed} }`;
};
const fmtStage = (s) => {
  const lines = ['  {', `    time: ${s.time},`, `    shuffle: ${JSON.stringify(s.shuffle).replace(/,/g, ', ')},`, '    map: ['];
  s.map.forEach((r) => lines.push(`      '${r}',`));
  lines.push('    ],');
  if (s.blink) lines.push(`    blink: { period: ${s.blink.period}, warn: ${s.blink.warn} },`);
  lines.push('    hazards: [');
  s.hazards.forEach((h) => lines.push(`      ${fmtHazard(h)},`));
  lines.push('    ],', '  },');
  return lines.join('\n');
};

let out = src;
const report = [];
for (const [name, list] of [['EASY', EASY], ['NORMAL', NORMAL], ['HARD', HARD], ['EXPERT', EXPERT]]) {
