      return s;
    }
    return { ...st, hazards: st.hazards.map((h) => ({ ...h, speed: round1(h.speed * SLOW[name]) })) };
  });
  // 그 배열 부분만 바꿔 끼움 (주석·순서는 그대로)
  const start = out.indexOf(`const ${name} = [`);
