// 추격 빨강(chase)을 같은 자리에서 출발하는 튕기는 빨강(bounce)으로 바꿈. 같은 형식으로 다시 씀
const fs = require('fs');
const path = process.argv[2];
const src = fs.readFileSync(path, 'utf8');
eval(src.replace(/^const /gm, 'var '));
const W = 6, H = 8;
const round1 = (v) => Math.round(v * 10) / 10;

function toBounce(st, h) {
  const m = st.map;
  const walk = (x, y) => x >= 0 && x < W && y >= 0 && y < H && m[y][x] !== '#' && m[y][x] !== 'G';
  // 그 방향으로 몇 칸 오갈 수 있는지 (출발 칸 포함, 양쪽으로)
  const span = (dx, dy) => {
    let n = 1;
    for (let k = 1; walk(h.x + dx * k, h.y + dy * k); k++) n++;
    for (let k = 1; walk(h.x - dx * k, h.y - dy * k); k++) n++;
    return n;
  };
  const options = [[1, 0], [0, 1], [1, 1], [1, -1]]
    .map(([dx, dy]) => ({ dx, dy, n: span(dx, dy) }))
    .filter((o) => o.n >= 3);
  // 가로 → 세로 → 대각선 순서로, 3칸 이상 오갈 수 있는 첫 방향
  const pick = options[0] || { dx: 1, dy: 0 };
  // 출발 방향은 갈 수 있는 쪽으로
  const sign = walk(h.x + pick.dx, h.y + pick.dy) ? 1 : -1;
  return { type: 'bounce', x: h.x, y: h.y, dx: pick.dx * sign, dy: pick.dy * sign, speed: round1(h.speed * 1.4) };
}

const fmtHazard = (h) => {
  if (h.type === 'sweep') return `{ type: 'sweep', axis: '${h.axis}', pos: ${h.pos}, dir: ${h.dir}, speed: ${h.speed} }`;
  if (h.type === 'chase') return `{ type: 'chase', x: ${h.x}, y: ${h.y}, speed: ${h.speed} }`;
  return `{ type: 'bounce', x: ${h.x}, y: ${h.y}, dx: ${h.dx}, dy: ${h.dy}, speed: ${h.speed} }`;
};
const fmtStage = (s) => {
  const lines = ['  {', `    time: ${s.time},`, `    shuffle: ${JSON.stringify(s.shuffle).replace(/,/g, ', ')},`, '    map: ['];
  s.map.forEach((r) => lines.push(`      '${r}',`));
  lines.push('    ],');
  if (s.blink) lines.push(`    blink: { period: ${s.blink.period}, warn: ${s.blink.warn} },`);
  lines.push('    hazards: [');
  s.hazards.forEach((h) => lines.push(`      ${fmtHazard(h)},`));
  lines.push('    ],', '  },');
  return lines.join('\n');
};

let out = src;
const report = [];
const label = { EASY: '초급', NORMAL: '중급', HARD: '고급', EXPERT: '특급' };
for (const [name, list] of [['EASY', EASY], ['NORMAL', NORMAL], ['HARD', HARD], ['EXPERT', EXPERT]]) {
  const next = list.map((st, i) => {
    const changed = [];
    const hazards = st.hazards.map((h) => {
      if (h.type !== 'chase') return h;
      const b = toBounce(st, h);
      changed.push(`(${h.x},${h.y}) ${b.dx},${b.dy} ×${b.speed}`);
      return b;
    });
    if (changed.length) report.push(`${label[name]}${i + 1}: ${changed.join(' / ')}`);
    return { ...st, hazards };
  });
  const start = out.indexOf(`const ${name} = [`);
  const end = out.indexOf('\n];', start) + 3;
  out = out.slice(0, start) + `const ${name} = [\n${next.map(fmtStage).join('\n')}\n];` + out.slice(end);
}
fs.writeFileSync(path, out);
console.log(report.join('\n'));
console.log('chase left:', (out.match(/type: 'chase'/g) || []).length);

