// 육각형 → 굴러가는 크리스탈 볼
const fs = require('fs');
process.chdir(process.argv[2]);
const patch = (p, rep) => {
  let s = fs.readFileSync(p, 'utf8');
  for (const [a, b] of rep) {
    if (s.split(a).length !== 2) throw new Error(p + ' miss ' + a.slice(0, 60));
    s = s.replace(a, () => b);
  }
  fs.writeFileSync(p, s);
};

// ── HTML: .hex → .orb (+ 굴러가는 표면) ──
let h = fs.readFileSync('index.html', 'utf8');
const n0 = h.split('<div class="hex">').length - 1;
if (n0 !== 2) throw new Error('html hex ' + n0);
h = h.split('<div class="hex">').join('<div class="orb">\n            <div class="orb-surface"></div>');
fs.writeFileSync('index.html', h);

// ── CSS ──
let c = fs.readFileSync('style.css', 'utf8');
c = c.split('.player.snap .hex').join('.player.snap .orb, .player.snap .orb-surface');
