// 크리스탈 볼: 서 있기 / 구르는 중 / 금 / 깨짐 확대 캡처
import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const DIR = process.argv[2];
const PORT = 9560 + Math.floor(Math.random() * 30);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const edge = spawn(EDGE, ['--headless=new', '--disable-gpu', '--no-first-run', `--user-data-dir=${DIR}/edge-orb`, `--remote-debugging-port=${PORT}`, 'about:blank']);
let ws;
try {
  let target;
  for (let i = 0; i < 40 && !target; i++) { await sleep(250); try { target = (await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()).find((t) => t.type === 'page'); } catch {} }
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r) => ws.addEventListener('open', r));
  let id = 0; const pending = new Map(); const errors = [];
  ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.exception?.description); });
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.result?.value;
  const shotPlayer = async (name) => {
    const r = await ev(`(() => { const b = document.getElementById('player').getBoundingClientRect(); return [b.left - 6, b.top - 6, b.width + 12, b.height + 12]; })()`);
    writeFileSync(`${DIR}/${name}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png', clip: { x: r[0], y: r[1], width: r[2], height: r[3], scale: 6 } })).result.data, 'base64'));
  };
  const key = (k) => ev(`document.dispatchEvent(new KeyboardEvent('keydown', { key: '${k}' }))`);
  await send('Page.enable'); await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
  await send('Page.navigate', { url: 'file:///D:/Gitasin/cybercube/www/index.html' });
  await sleep(800);
  await ev(`localStorage.setItem('cybercube.progress', JSON.stringify({ stars: {}, best: {}, name: 'T', sound: false })); localStorage.setItem('cybercube.hideIntro', '1'); localStorage.setItem('cybercube.lang', 'ko'); 1`);
  await send('Page.reload'); await sleep(1200);
  await ev(`document.querySelector('#stageGrid .stage-btn').click()`); await sleep(2400);
  await shotPlayer('orb-idle');
  await key('d'); await sleep(55); await shotPlayer('orb-roll-a');
  await sleep(45); await shotPlayer('orb-roll-b');
  await sleep(300); await shotPlayer('orb-after');
  console.log('roll vars:', await ev(`(() => { const p = document.getElementById('player'); return ['--tx', '--ty', '--ball'].map((v) => v + '=' + p.style.getPropertyValue(v)).join(' '); })()`));
  // 빨강이 오가는 줄에서 맞기
  await key('a'); await sleep(200);
  for (let k = 0; k < 3; k++) { await key('w'); await sleep(160); }
  const seen = {}; const end = Date.now() + 40000;
  while (Date.now() < end) {
    const [lives, shards] = (await ev(`document.getElementById('lives').textContent + '|' + document.querySelectorAll('#player .shard').length`)).split('|');
    if (lives === '♥♥♡' && !seen.a) { seen.a = 1; await sleep(1300); await shotPlayer('orb-crack1'); }
    if (lives === '♥♡♡' && !seen.b) { seen.b = 1; await sleep(1300); await shotPlayer('orb-crack2'); }
    if (Number(shards) > 5 && !seen.c) { seen.c = 1; await sleep(120); await shotPlayer('orb-shatter'); console.log('shards', shards); break; }
    await sleep(50);
  }
  console.log('errors:', errors.length ? errors : 'none');
} catch (e) { console.log('ERROR', e.message); } finally { ws?.close(); edge.kill(); }

