// 판 회전·뒤집기 제거 → 판 둘레 벽(뚫린 곳으로 가면 떨어짐) + 중급부터 좌우 기울기(볼이 낮은 쪽으로 굴러감)
const fs = require('fs');
process.chdir(process.argv[2]);
const patch = (p, rep) => {
  let s = fs.readFileSync(p, 'utf8');
  for (const [a, b] of rep) {
    if (s.split(a).length !== 2) throw new Error(p + ' miss ' + a.slice(0, 70));
    s = s.replace(a, () => b);
  }
  fs.writeFileSync(p, s);
};
const cut = (p, startMark, endMark, insert = '') => {
  let s = fs.readFileSync(p, 'utf8');
  const a = s.indexOf(startMark);
  const b = s.indexOf(endMark, a);
  if (a < 0 || b < 0) throw new Error(p + ' cut markers ' + startMark.slice(0, 40));
  s = s.slice(0, a) + insert + s.slice(b);
  fs.writeFileSync(p, s);
};

// ── 스테이지 데이터: 회전·뒤집기 → 벽 + 기울기 ──
{
  let s = fs.readFileSync('stages.js', 'utf8');
