        if (!wallBlocks(dir, 0)) fallOff(dir, 0);   // 뚫린 벽 쪽이면 떨어짐, 막혀 있으면 기대어 멈춤
      } else if (canStep(nx, state.py)) {
        move(dir, 0);
      }
    }
  }

`);
