// 벽·떨어짐·기울기 시험
import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const DIR = process.argv[2];
const PORT = 9600 + Math.floor(Math.random() * 30);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const edge = spawn(EDGE, ['--headless=new', '--disable-gpu', '--no-first-run', `--user-data-dir=${DIR}/edge-walls`, `--remote-debugging-port=${PORT}`, 'about:blank']);
let ws;
try {
  let target;
  for (let i = 0; i < 40 && !target; i++) { await sleep(250); try { target = (await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()).find((t) => t.type === 'page'); } catch {} }
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r) => ws.addEventListener('open', r));
  let id = 0; const pending = new Map(); const errors = [];
  ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.exception?.description); });
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.result?.value;
  const shot = async (name) => writeFileSync(`${DIR}/${name}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'));
  const key = async (k, wait = 220) => { await ev(`document.dispatchEvent(new KeyboardEvent('keydown', { key: '${k}' }))`); await sleep(wait); };
  const pos = () => ev(`(() => { const b = document.getElementById('board').getBoundingClientRect(); const p = document.getElementById('player').getBoundingClientRect(); return [Math.round((p.left - b.left) / (b.width / 6)), Math.round((p.top - b.top) / (b.height / 8))]; })()`);
  const lives = () => ev(`document.getElementById('lives').textContent`);
  const gaps = (side) => ev(`[...document.querySelectorAll('#board .wall.${side}')].map((w, i) => w.classList.contains('gap') ? i : -1).filter((i) => i >= 0)`);

  await send('Page.enable'); await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
  await send('Page.navigate', { url: 'file:///D:/Gitasin/cybercube/www/index.html' });
  await sleep(800);
  await ev(`(() => { const stars = {}; for (let i = 0; i < 47; i++) stars[i] = 2; localStorage.setItem('cybercube.progress', JSON.stringify({ stars, best: {}, name: 'T', sound: false, tab: 0 })); localStorage.setItem('cybercube.hideIntro', '1'); localStorage.setItem('cybercube.lang', 'ko'); return 1; })()`);
  await send('Page.reload'); await sleep(1200);

  // ── 초급 12: 벽 60% ──
  await ev(`document.querySelectorAll('#stageGrid .stage-btn')[11].click()`); await sleep(2400);
  const walls = await ev(`document.querySelectorAll('#board .wall').length + ' walls, ' + document.querySelectorAll('#board .wall.gap').length + ' gaps'`);
  const bottomGaps = await gaps('bottom');
  console.log('E12:', walls, '| bottom gaps', JSON.stringify(bottomGaps), '| start', JSON.stringify(await pos()), await lives());
  await shot('walls-e12');
  // 바닥 줄에서 아래로 밀기: 막힌 곳 → 그대로, 뚫린 곳 → 떨어짐
  const p0 = await pos();
  await key('s', 300);
  console.log('  push down at start col', p0[0], '(protected wall) →', JSON.stringify(await pos()), await lives());
  const gapCol = bottomGaps.find((c) => c !== p0[0]);
  if (gapCol != null) {
    for (let k = 0; k < 6 && (await pos())[0] !== gapCol; k++) await key((await pos())[0] < gapCol ? 'd' : 'a');
    console.log('  moved to bottom gap col', gapCol, '→', JSON.stringify(await pos()), await lives());
    await key('s', 120); await shot('fall-mid');
    await sleep(900);
    console.log('  after falling →', JSON.stringify(await pos()), await lives());
  }

