`      playerEl.classList.remove('falling');
      playerEl.classList.add('snap'); // 시작 지점으로는 미끄러지지 않고 바로
      st.px = st.startX;
      st.py = st.startY;
      st.phase = 'play';`],
]);
let c=fs.readFileSync('style.css','utf8');
const a=`/* 판 밖으로 떨어짐: 굴러 나가며 작아지고 사라짐 → 원래 칸에서 다시 나타남 */
.player.falling { animation: fall 0.65s ease-in forwards; }
.player.respawn { animation: respawn 0.35s ease-out; }
@keyframes fall {
  0% { scale: 1; opacity: 1; translate: 0 0; }
  100% { scale: 0.2; opacity: 0; translate: calc(var(--fdx) * 30%) calc(var(--fdy) * 30%); }
}`;
if(c.split(a).length!==2) throw new Error('css fall');
c=c.replace(a,()=>`/* 판 밖으로 떨어짐: 판 밖 칸까지 굴러 나간 뒤(이동 0.15초) 아래로 떨어지듯 작아지고 어두워지며 사라짐
   → 스테이지 시작 지점에서 다시 나타남 */
.player.falling { animation: fall 0.65s cubic-bezier(0.5, 0, 0.9, 0.6) forwards; }
.player.respawn { animation: respawn 0.4s ease-out; }
@keyframes fall {
  0%, 22% { scale: 1; opacity: 1; translate: 0 0; filter: brightness(1); }
  100% { scale: 0.05; opacity: 0; translate: calc(var(--fdx) * 18%) calc(var(--fdy) * 18% + 25%); filter: brightness(0.25); }
}`);
fs.writeFileSync('style.css',c);
console.log('ok');
