  }
  function levelBoard() {
    if (state) { state.tilt = 0; state.rollAcc = 0; }
    board.style.transform = '';
  }
  function updateTilt(dt) {
    const tl = state.tiltCfg;
    if (!tl) return;
    state.tiltLeft -= dt;
    if (state.tiltLeft <= 0) {
      if (state.tiltPhase === 'flat') {
        state.tiltPhase = 'tilted';
        const deg = rand(tl.angle[0], tl.angle[1]) + state.tiltBonus;
        setTilt((Math.random() < 0.5 ? -1 : 1) * deg);
        state.tiltLeft = rand(tl.tilted[0], tl.tilted[1]);
        state.rollAcc = -0.35; // 기울어지는 동안(0.6초 남짓)은 잠깐 기다렸다 굴러감
        sfx.tilt();
      } else {
        state.tiltPhase = 'flat';
        setTilt(0);
        state.rollAcc = 0;
        state.tiltLeft = rand(tl.flat[0], tl.flat[1]);
      }
    }
    if (!state.tilt) return;
    // 굴러가는 속도: 5° ≈ 1.5칸/초, 10° ≈ 3칸/초, 최대 3.5칸/초
    state.rollAcc += dt * Math.min(3.5, Math.abs(state.tilt) * 0.3);
    if (state.rollAcc >= 1) {
      state.rollAcc -= 1;
      const dir = Math.sign(state.tilt);
      const nx = state.px + dir;
      if (!inside(nx, state.py)) {
        if (!wallBlocks(dir, 0)) fallOff(dir, 0);   // 뚫린 벽 쪽이면 떨어짐, 막혀 있으면 기대어 멈춤
      } else if (canStep(nx, state.py)) {
        move(dir, 0);
      }
    }
  }
