  await send('Page.navigate', { url: 'file:///D:/Gitasin/cybercube/www/index.html' });
  await sleep(800);
  await ev(`(() => { const stars = {}; for (let i = 0; i < 47; i++) stars[i] = 2; localStorage.setItem('cybercube.progress', JSON.stringify({ stars, best: {}, name: 'T', sound: false, tab: 1 })); localStorage.setItem('cybercube.hideIntro', '1'); localStorage.setItem('cybercube.lang', 'ko'); return 1; })()`);
  await send('Page.reload'); await sleep(1200);
  // 중급 1: 시험용으로 곧바로 기울게
  await ev(`TIERS[1].tilt.flat = [0.3, 0.4]; TIERS[1].tilt.tilted = [9, 9]; document.querySelectorAll('#stageGrid .stage-btn')[0].click(); 1`);
  await sleep(2100);
