// 기울기 방향 확장 (초급 좌우 / 중급 +위아래 / 고급·특급 +대각선) + 시연 장면 2개
const fs = require('fs');
process.chdir(process.argv[2]);
const patch = (p, rep) => {
  let s = fs.readFileSync(p, 'utf8');
  for (const [a, b] of rep) {
    if (s.split(a).length !== 2) throw new Error(p + ' miss ' + a.slice(0, 70));
    s = s.replace(a, () => b);
  }
  fs.writeFileSync(p, s);
};

// ── 스테이지: 난이도별 기우는 방향 ──
patch('stages.js', [
  [`// tilt: 판이 좌우로 기울어짐 (볼이 낮은 쪽으로 저절로 굴러감)`,
   `// tilt: 판이 기울어짐 (볼이 낮은 쪽으로 저절로 굴러감)
//   dirs = 기우는 방향 종류 ('h' 좌우, 'v' 위아래, 'd' 대각선) 중 랜덤`],
  [`tilt: { angle: [2, 4], stepUp: 3,`, `tilt: { dirs: ['h'], angle: [2, 4], stepUp: 3,`],
  [`tilt: { angle: [5, 10], stepUp: 2,`, `tilt: { dirs: ['h', 'v'], angle: [5, 10], stepUp: 2,`],
  [`tilt: { angle: [7, 13], stepUp: 2,`, `tilt: { dirs: ['h', 'v', 'd'], angle: [7, 13], stepUp: 2,`],
  [`tilt: { angle: [9, 16], stepUp: 2,`, `tilt: { dirs: ['h', 'v', 'd'], angle: [9, 16], stepUp: 2,`],
]);

// ── 게임: 기울기를 (가로, 세로) 두 방향으로 ──
{
  let g = fs.readFileSync('game.js', 'utf8');
  const a = g.indexOf('  // 화면에서 보이는 기울기는 실제 각도의 2.4배');
  const b = g.indexOf('  function updateTilt(dt) {');
  const c = g.indexOf('\n  }\n', b) + 4;
  if (a < 0 || b < 0) throw new Error('tilt markers');
  g = g.slice(0, a) + `  // 기울기 모습: 화면에서는 실제 각도의 2.4배(최대 30°) → 작은 각도도 기울어진 게 확실히 보임
  // ax: +는 오른쪽이 낮음, ay: +는 아래쪽이 낮음. 낮아진 쪽은 멀어져 작고 어둡게, 판 그림자도 그쪽으로 (style.css의 .tilted)
  // 시연 화면에서도 같이 씀
  function tiltVisual(el, ax, ay) {
    const sx = Math.max(-30, Math.min(30, ax * 2.4));
    const sy = Math.max(-30, Math.min(30, ay * 2.4));
    const on = ax !== 0 || ay !== 0;
    el.style.transform = on ? \`perspective(700px) rotateX(\${(-sy).toFixed(1)}deg) rotateY(\${sx.toFixed(1)}deg)\` : '';
    el.classList.toggle('tilted', on);
    if (!on) return;
    el.style.setProperty('--tilt-amt', Math.min(1, Math.hypot(sx, sy) / 24).toFixed(2));
    el.style.setProperty('--tilt-dir', \`\${Math.round((Math.atan2(ax, -ay) * 180) / Math.PI)}deg\`); // 그라데이션: 높은 쪽 → 낮은 쪽
    el.style.setProperty('--tsx', Math.sign(ax));
    el.style.setProperty('--tsy', Math.sign(ay));
  }
  window.tiltVisual = tiltVisual;

  function setTilt(ax, ay) {
    state.tiltX = ax;
    state.tiltY = ay;
    tiltVisual(board, ax, ay);
  }

  function levelBoard() {
    if (state) { state.tiltX = 0; state.tiltY = 0; state.rollAcc = 0; state.rollVel = 0; }
    tiltVisual(board, 0, 0);
  }

  // 굴러갈 수 있는 한 칸 (판 밖이면 뚫린 벽일 때만 = 떨어짐)
  const rollable = (dx, dy) => {
    const nx = state.px + dx;
    const ny = state.py + dy;
    return inside(nx, ny) ? canStep(nx, ny) : !wallBlocks(dx, dy);
  };

  function updateTilt(dt) {
    const tl = state.tiltCfg;
    if (!tl) return;
    state.tiltLeft -= dt;
    if (state.tiltLeft <= 0) {
      if (state.tiltPhase === 'flat') {
        state.tiltPhase = 'tilted';
        const deg = rand(tl.angle[0], tl.angle[1]) + state.tiltBonus;
        const kinds = tl.dirs || ['h'];
        const kind = kinds[Math.floor(Math.random() * kinds.length)];
        const sx = Math.random() < 0.5 ? -1 : 1;
        const sy = Math.random() < 0.5 ? -1 : 1;
        if (kind === 'h') setTilt(sx * deg, 0);
        else if (kind === 'v') setTilt(0, sy * deg);
        else setTilt(sx * deg * 0.75, sy * deg * 0.75); // 대각선: 두 방향으로 나눠서 (전체 기울기는 비슷하게)
        state.tiltLeft = rand(tl.tilted[0], tl.tilted[1]);
        state.rollAcc = 0;
        state.rollVel = 0;
        state.rollWait = 0.45; // 판이 기울어지는 동안은 잠깐 기다렸다 굴러감
        state.resting = false;
        sfx.tilt();
      } else {
        state.tiltPhase = 'flat';
        setTilt(0, 0);
        state.rollAcc = 0;
        state.rollVel = 0;
        state.tiltLeft = rand(tl.flat[0], tl.flat[1]);
      }
    }
    if (!state.tiltX && !state.tiltY) return;
    if (state.rollWait > 0) { state.rollWait -= dt; return; }
    // 중력처럼 점점 빨라짐: 가속도·최고 속도 모두 기울기에 비례 (5° → 최고 2칸/초, 10° → 4칸/초, 최대 5칸/초)
    const a = Math.hypot(state.tiltX, state.tiltY);
    const sx = Math.sign(state.tiltX);
    const sy = Math.sign(state.tiltY);
    // 낮은 쪽으로 한 칸. 대각선이 막히면 벽을 따라 미끄러지듯 가로·세로 중 갈 수 있는 쪽
    const tries = sx && sy ? [[sx, sy], [sx, 0], [0, sy]] : [[sx, sy]];
    const step = tries.find(([dx, dy]) => rollable(dx, dy));
    if (!step) {
      // 벽·막힌 블록: 굴러오던 힘이 있으면 한 번 부딪혀 튕기고, 그다음엔 기대어 멈춤
      if (!state.resting && state.rollVel > 0.6) {
        const [dx, dy] = tries[0];
        if (!inside(state.px + dx, state.py + dy)) wallHit(dx, dy); else bumpPlayer(dx, dy);
      }
      state.resting = true;
      state.rollVel = 0;
      state.rollAcc = 0;
      return;
    }
    state.rollVel = Math.min(Math.min(5, a * 0.4), state.rollVel + a * 0.45 * dt);
    state.rollAcc += state.rollVel * dt;
    if (state.rollAcc >= 1) {
      state.rollAcc -= 1;
      const [dx, dy] = step;
      if (!inside(state.px + dx, state.py + dy)) fallOff(dx, dy);       // 뚫린 벽 쪽이면 떨어짐
      else move(dx, dy, Math.min(0.7, Math.max(0.12, 1 / state.rollVel))); // 다음 칸까지 이어서 굴러감
    }
  }
` + g.slice(c);
  g = g.replace(`      tilt: 0,                     // 지금 기울기(°): +는 오른쪽이 낮음, -는 왼쪽이 낮음`,
    `      tiltX: 0, tiltY: 0,          // 지금 기울기(°): tiltX +는 오른쪽이 낮음, tiltY +는 아래쪽이 낮음`);
  if (/state\.tilt\b(?!X|Y|Cfg|Phase|Left|Bonus)/.test(g)) throw new Error('leftover state.tilt: ' + g.match(/.{30}state\.tilt\b(?!X|Y|Cfg|Phase|Left|Bonus).{30}/)[0]);
  fs.writeFileSync('game.js', g);
}

// ── 스타일: 기운 방향에 맞춘 빛·그림자 ──
{
  let c = fs.readFileSync('style.css', 'utf8');
  const a = `.board.tilt-right::after { opacity: var(--tilt-amt, 0.5); background: linear-gradient(90deg, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0) 35%, rgba(0, 0, 0, 0) 55%, rgba(0, 0, 0, 0.5)); }
.board.tilt-left::after { opacity: var(--tilt-amt, 0.5); background: linear-gradient(270deg, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0) 35%, rgba(0, 0, 0, 0) 55%, rgba(0, 0, 0, 0.5)); }
.board.tilt-right { box-shadow: 0 0 0 4px var(--frame, #24272f), 22px 18px 34px rgba(0, 0, 0, 0.75); }
.board.tilt-left { box-shadow: 0 0 0 4px var(--frame, #24272f), -22px 18px 34px rgba(0, 0, 0, 0.75); }`;
  if (c.split(a).length !== 2) throw new Error('css tilt');
  c = c.replace(a, () => `/* --tilt-dir: 높은 쪽 → 낮은 쪽 방향, --tsx/--tsy: 낮은 쪽 (-1, 0, 1) */
.board.tilted::after { opacity: var(--tilt-amt, 0.5); background: linear-gradient(var(--tilt-dir, 90deg), rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0) 35%, rgba(0, 0, 0, 0) 55%, rgba(0, 0, 0, 0.5)); }
.board.tilted { box-shadow: 0 0 0 4px var(--frame, #24272f), calc(var(--tsx, 0) * 22px) calc(14px + var(--tsy, 0) * 16px) 34px rgba(0, 0, 0, 0.75); }`);
  fs.writeFileSync('style.css', c);
}

