// 생명 → 에너지, 아이템(모래시계·금), 쇳덩어리 → 금빛 볼
const fs = require('fs');
const root = process.argv[2]; // cybercube 폴더
process.chdir(root + '/www');
const patch = (p, rep) => {
  let s = fs.readFileSync(p, 'utf8');
  for (const [a, b] of rep) {
    if (s.split(a).length !== 2) throw new Error(p + ' miss ' + a.slice(0, 70));
    s = s.replace(a, () => b);
  }
  fs.writeFileSync(p, s);
};

// ── 스테이지: 난이도별 아이템 수 ──
patch('stages.js', [
  [`//   dirs = 기우는 방향 종류 ('h' 좌우, 'v' 위아래, 'd' 대각선) 중 랜덤`,
   `//   dirs = 기우는 방향 종류 ('h' 좌우, 'v' 위아래, 'd' 대각선) 중 랜덤
// items: 스테이지마다 놓이는 아이템 수 (time = 모래시계: 시간 +20초, gold = 금: 최대 에너지 +1, 계속 유지)`],
  [`  { name: 'EASY', stages: EASY, walls: [1, 0.6],`, `  { name: 'EASY', stages: EASY, items: { time: 5, gold: 2 }, walls: [1, 0.6],`],
  [`  { name: 'NORMAL', stages: NORMAL, walls: [0.8, 0.5],`, `  { name: 'NORMAL', stages: NORMAL, items: { time: 6, gold: 3 }, walls: [0.8, 0.5],`],
  [`  { name: 'HARD', stages: HARD, walls: [0.65, 0.35],`, `  { name: 'HARD', stages: HARD, items: { time: 7, gold: 3 }, walls: [0.65, 0.35],`],
  [`  { name: 'EXPERT', stages: EXPERT, walls: [0.5, 0.2],`, `  { name: 'EXPERT', stages: EXPERT, items: { time: 8, gold: 4 }, walls: [0.5, 0.2],`],
]);

// ── 게임 ──
patch('game.js', [
  [`  const MAX_LIVES = 3;`, `  const BASE_ENERGY = 3;        // 처음 에너지 (빨강·떨어짐 3번이면 깨짐)
  const MAX_GOLD = 6;           // 금은 6개까지 쌓임 → 최대 에너지 9
  const TIME_BONUS = 20;        // 모래시계 하나에 늘어나는 시간 (초)
  const maxEnergy = () => BASE_ENERGY + Math.min(MAX_GOLD, progress.gold || 0);`],
  [`  let progress = { stars: {}, best: {}, name: '', sound: true, updated: 0 };`,
   `  // gold: 지금까지 먹은 금 (볼이 단단해짐, 계속 유지), goldTaken: 스테이지별로 이미 먹은 금 수 (다시 안 나옴)
  let progress = { stars: {}, best: {}, name: '', sound: true, updated: 0, gold: 0, goldTaken: {} };`],
  [`    progress.name = merged.name || progress.name;`, `    progress.name = merged.name || progress.name;
    progress.gold = Math.max(progress.gold || 0, merged.gold || 0);
    Object.entries(merged.goldTaken || {}).forEach(([k, v]) => { progress.goldTaken[k] = Math.max(progress.goldTaken[k] || 0, v); });
    applyBallLook();`],
  [`      lives: MAX_LIVES,`, `      lives: maxEnergy(),          // 에너지 (화면에서는 '에너지' 칸)
      maxLives: maxEnergy(),
      timeMax: def.time,           // 모래시계를 먹으면 늘어남 (시간 막대 기준)`],
  [`    setupWalls(n);`, `    setupWalls(n);
    setupItems(n);`],
  // 먹기
  [`    state.px = nx;
    state.py = ny;
    const i = idx(nx, ny);`, `    state.px = nx;
    state.py = ny;
    const i = idx(nx, ny);
    collectItem(i);`],
  // 파랑 순간이동은 아이템 칸을 피함
  [`      if ((t === '.' || t === 'D') && red[i] === 0 && i !== idx(state.px, state.py)) pool.push(i);`,
   `      if ((t === '.' || t === 'D') && red[i] === 0 && i !== idx(state.px, state.py) && !state.items.has(i)) pool.push(i);`],
  // 금 간 모습: 남은 에너지 기준
  [`    const crack = String(Math.min(2, MAX_LIVES - state.lives));`,
   `    const crack = String(state.lives <= 1 ? 2 : state.lives <= 2 ? 1 : 0); // 에너지 2 남으면 작은 금, 1 남으면 큰 금`],
