    for (let i = spots.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [spots[i], spots[j]] = [spots[j], spots[i]]; }
    // 앞자리부터 금 → 모래시계. 이미 먹은 금 자리는 비워 둠
    const taken = progress.goldTaken[n] || 0;
