  const GOLD = { b1: [255, 246, 207], b2: [246, 201, 69], b3: [192, 138, 18], b4: [110, 74, 5], band: [255, 228, 120], glow: [255, 196, 50] };
  function applyBallLook(flash = false) {
    const t = Math.min(MAX_GOLD, progress.gold || 0) / MAX_GOLD;
    const mix = (a, b) => a.map((v, i) => Math.round(v + (b[i] - v) * t)).join(', ');
    ['b1', 'b2', 'b3', 'b4'].forEach((k) => playerEl.style.setProperty(\`--\${k}\`, \`rgb(\${mix(IRON[k], GOLD[k])})\`));
    playerEl.style.setProperty('--band', \`rgba(\${mix(IRON.band, GOLD.band)}, 0.9)\`);
    playerEl.style.setProperty('--glow-c', \`rgba(\${mix(IRON.glow, GOLD.glow)}, \${(0.45 + 0.5 * t).toFixed(2)})\`);
    playerEl.style.setProperty('--spark', (0.3 + 0.7 * t).toFixed(2));
    playerEl.classList.toggle('golden', t > 0);
    if (flash) {
      playerEl.classList.remove('gold-flash');
      void playerEl.offsetWidth;
      playerEl.classList.add('gold-flash');
    }
  }

  // ── 판 둘레 벽 ──`],
