// 에너지·아이템·볼 색 시험
import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const DIR = process.argv[2];
const PORT = 9640 + Math.floor(Math.random() * 30);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const edge = spawn(EDGE, ['--headless=new', '--disable-gpu', '--no-first-run', `--user-data-dir=${DIR}/edge-items`, `--remote-debugging-port=${PORT}`, 'about:blank']);
let ws;
try {
  let target;
  for (let i = 0; i < 40 && !target; i++) { await sleep(250); try { target = (await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()).find((t) => t.type === 'page'); } catch {} }
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r) => ws.addEventListener('open', r));
  let id = 0; const pending = new Map(); const errors = [];
  ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.exception?.description); });
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.result?.value;
  const shot = async (name) => writeFileSync(`${DIR}/${name}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'));
  const key = async (k, wait = 260) => { await ev(`document.dispatchEvent(new KeyboardEvent('keydown', { key: '${k}' }))`); await sleep(wait); };
  const pos = () => ev(`(() => { const b = document.getElementById('board').getBoundingClientRect(); const p = document.getElementById('player').getBoundingClientRect(); return [Math.round((p.left - b.left) / (b.width / 6)), Math.round((p.top - b.top) / (b.height / 8))]; })()`);
  const hud = () => ev(`'energy ' + document.querySelectorAll('#lives .pip.on').length + '/' + document.querySelectorAll('#lives .pip').length + ' | time ' + document.getElementById('time')?.textContent + ' | items ' + [...document.querySelectorAll('#board .item:not(.got)')].map(e => e.classList[1][0] + e.style.getPropertyValue('--x') + e.style.getPropertyValue('--y')).join(',')`);
  const items = () => ev(`[...document.querySelectorAll('#board .item:not(.got)')].map(e => [e.classList[1], +e.style.getPropertyValue('--x'), +e.style.getPropertyValue('--y')])`);
  const go = async (tx, ty) => { for (let k = 0; k < 14; k++) { const p = await pos(); if (p[0] === tx && p[1] === ty) return true; const dx = Math.sign(tx - p[0]), dy = Math.sign(ty - p[1]); await key(({ '1,0': 'd', '-1,0': 'a', '0,1': 's', '0,-1': 'w', '1,1': 'c', '-1,1': 'z', '1,-1': 'e', '-1,-1': 'q' })[dx + ',' + dy]); } return false; };

  await send('Page.enable'); await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
  await send('Page.navigate', { url: 'file:///D:/Gitasin/cybercube/www/index.html' });
  await sleep(800);
  await ev(`(() => { localStorage.setItem('cybercube.progress', JSON.stringify({ stars: {}, best: {}, name: 'T', sound: false, tab: 0 })); localStorage.setItem('cybercube.hideIntro', '1'); localStorage.setItem('cybercube.lang', 'ko'); return 1; })()`);
  await send('Page.reload'); await sleep(1200);
  await ev(`TIERS[0].tilt.flat = [99, 99]; document.querySelectorAll('#stageGrid .stage-btn')[0].click()`); await sleep(2400);
  console.log('E1 start', JSON.stringify(await pos()), await hud());
  console.log('ball b2', await ev(`document.getElementById('player').style.getPropertyValue('--b2')`));
  await shot('items-e1');
  const list = await items();
  // 금 하나 먹기 (빨강 밟을 수 있으니 무적으로)
  await ev(`1`);
  const gold = list.find((i) => i[0] === 'gold');
  const time = list.find((i) => i[0] === 'time');
  const timeBefore = await ev(`document.getElementById('time')?.textContent`);
  console.log('go to time', JSON.stringify(time), await go(time[1], time[2]), await hud());
  console.log('go to gold', JSON.stringify(gold), await go(gold[1], gold[2]), await hud());
  console.log('ball b2', await ev(`document.getElementById('player').style.getPropertyValue('--b2')`), 'golden', await ev(`document.getElementById('player').className`));
  console.log('saved', await ev(`localStorage.getItem('cybercube.progress')`));
  await sleep(300); await shot('items-gold');
  // 다시 시작: 먹은 금은 사라져야 함, 에너지 4
  await ev(`document.getElementById('backBtn').click()`); await sleep(400);
  await ev(`document.querySelectorAll('#stageGrid .stage-btn')[0].click()`); await sleep(2400);
  console.log('restart', await hud());
  // 6개 금 → 볼 완전 금
  await ev(`(() => { const p = JSON.parse(localStorage.getItem('cybercube.progress')); p.gold = 6; localStorage.setItem('cybercube.progress', JSON.stringify(p)); return 1; })()`);
  await send('Page.reload'); await sleep(1200);
  await ev(`TIERS[0].tilt.flat = [99, 99]; document.querySelectorAll('#stageGrid .stage-btn')[1].click()`); await sleep(2400);
  console.log('gold6', await hud()); await shot('items-gold6');
  console.log('errors:', errors.length ? errors : 'none');
} catch (e) { console.log('ERROR', e.stack); } finally { ws?.close(); edge.kill(); }

