/* ── 육각형 플레이어 ──
   .player       = 칸 이동 (translate)
     ::before    = 바닥 그림자 (회전 안 함)
     .orb        = 크리스탈 볼 + 금 (굴러가는 표면 무늬는 orb.js가 3D로 그림)
                   빛 효과(filter)를 이 층에 두고 will-change로 GPU가 통째로 돌림 → 구를 때 다시 그리지 않음
     ::after     = 고정 조명 (왼쪽 위). 육각형은 60° 대칭이라 다 구르면 모양이 딱 겹침
   이동과 회전은 같은 시간·같은 곡선 → 칸에 도착하는 순간 회전도 끝남 */
.player {
  --move: 0.15s;
  --ease: cubic-bezier(0.25, 0.8, 0.35, 1);
  --glow: drop-shadow(0 0 1px rgba(8, 20, 40, 0.9)) drop-shadow(0 0 6px var(--glow-c, rgba(180, 192, 212, 0.45)));
  position: absolute;
  left: 0;
  top: 0;
  width: calc(100% / var(--cols));
  height: calc(100% / var(--rows));
  transition: transform var(--move) var(--ease);
  will-change: transform;
  pointer-events: none;
  z-index: 2;
}
.player.diag { --move: 0.19s; } /* 대각선은 거리가 길어서 조금 더 길게 */
.player::before {
  content: "";
  position: absolute;
  inset: 22% 20% 12%;
  background: radial-gradient(ellipse at 50% 62%, rgba(0, 0, 0, 0.55) 0%, rgba(0, 0, 0, 0) 65%);
}
/* 크리스탈 볼
   .orb         = 볼 몸체 (둥글게 잘림). 판이 돌거나 뒤집힐 때만 --rot / --fx로 같이 돌아감
   .orb-lines   = 표면의 크리스탈 절단선·반짝이 점 (orb.js가 굴러간 각도만큼 3D로 회전해 그림)
   ::after      = 굴러도 제자리인 빛 (왼쪽 위 하이라이트, 가장자리 음영, 오른쪽 아래 굴절광) → 구르는 느낌 */
.player .orb {
  position: absolute;
  inset: 18%;
  border-radius: 50%;
  overflow: hidden;
  /* 쇳덩어리(처음) → 금을 먹을수록 황금 (색은 game.js의 applyBallLook이 --b1~--b4로) */
  background: radial-gradient(circle at 42% 38%, var(--b1, #e6e9ee) 0%, var(--b2, #9aa1ab) 45%, var(--b3, #5b616b) 80%, var(--b4, #2e3238) 100%);
  filter: var(--glow);
  transform: rotate(var(--rot, 0deg)) scaleX(var(--fx, 1)); /* --fx: 판이 뒤집히면 좌우 반전 */
  will-change: transform;
}
/* 표면 무늬(절단선·반짝이 점)는 orb.js가 3D로 돌려서 그림. 뒤쪽은 희미하게 비침 */
.player::after {
  content: "";
  position: absolute;
  inset: 18%;
  border-radius: 50%;
  pointer-events: none;
  background:
    radial-gradient(circle at 34% 28%, rgba(255, 255, 255, 0.95) 0 7%, rgba(255, 255, 255, 0.35) 13%, rgba(255, 255, 255, 0) 24%),
    radial-gradient(circle at 70% 76%, rgba(190, 245, 255, 0.55) 0%, rgba(190, 245, 255, 0) 30%),
    radial-gradient(circle at 50% 50%, rgba(255, 255, 255, 0) 52%, rgba(20, 70, 110, 0.35) 80%, rgba(8, 30, 60, 0.75) 100%);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.35);
}
.player.invincible { animation: blink 0.15s infinite alternate; }
/* 막힌 방향으로 밀었을 때 살짝 툭 부딪힘 (--bx, --by = 민 방향) */
.board .player.bump { animation: bump 0.16s ease-out; }

