import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const DIR = process.argv[2];
const PORT = 9680 + Math.floor(Math.random() * 30);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const edge = spawn(EDGE, ['--headless=new', '--disable-gpu', '--no-first-run', `--user-data-dir=${DIR}/edge-ball`, `--remote-debugging-port=${PORT}`, 'about:blank']);
let ws;
try {
  let target;
  for (let i = 0; i < 40 && !target; i++) { await sleep(250); try { target = (await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()).find((t) => t.type === 'page'); } catch {} }
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r) => ws.addEventListener('open', r));
  let id = 0; const pending = new Map(); const errors = [];
  ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.exception?.description); });
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.result?.value;
  await send('Page.enable'); await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 3, mobile: true });
  await send('Page.navigate', { url: 'file:///D:/Gitasin/cybercube/www/index.html' });
  await sleep(800);
  for (const g of [0, 2, 4, 6]) {
    await ev(`(() => { localStorage.setItem('cybercube.progress', JSON.stringify({ stars: {}, best: {}, name: 'T', sound: false, tab: 0, gold: ${g}, goldTaken: {} })); localStorage.setItem('cybercube.hideIntro', '1'); localStorage.setItem('cybercube.lang', 'ko'); return 1; })()`);
    await send('Page.reload'); await sleep(1200);
    await ev(`TIERS[0].tilt.flat = [99, 99]; document.querySelectorAll('#stageGrid .stage-btn')[0].click()`); await sleep(2600);
    const r = await ev(`(() => { const r = document.getElementById('player').getBoundingClientRect(); return [r.left, r.top, r.width, r.height]; })()`);
    const shot = await send('Page.captureScreenshot', { format: 'png', clip: { x: r[0] - 6, y: r[1] - 6, width: r[2] + 12, height: r[3] + 12, scale: 1 } });
    writeFileSync(`${DIR}/ball-${g}.png`, Buffer.from(shot.result.data, 'base64'));
    if (g === 6) writeFileSync(`${DIR}/hud-6.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png', clip: { x: 0, y: 60, width: 390, height: 80, scale: 1 } })).result.data, 'base64'));
    await ev(`document.getElementById('backBtn').click()`); await sleep(300);
  }
  console.log('errors:', errors.length ? errors : 'none');
} catch (e) { console.log('ERROR', e.stack); } finally { ws?.close(); edge.kill(); }
