// 아이템: 등급별 개수를 스테이지에 랜덤 배분, 잠깐 나타났다 사라짐
const fs = require('fs');
const W = 'D:/Gitasin/cybercube/www/';
const patch = (p, rep) => {
  let s = fs.readFileSync(W + p, 'utf8');
  for (const [a, b] of rep) {
    if (s.split(a).length !== 2) throw new Error(p + ' miss ' + a.slice(0, 70));
    s = s.replace(a, () => b);
  }
  fs.writeFileSync(W + p, s);
};

patch('stages.js', [[
  `// items: 스테이지마다 놓이는 아이템 수 (time = 모래시계: 시간 +20초, gold = 금: 최대 에너지 +1, 계속 유지)`,
  `// items: 등급(12스테이지) 전체에 나오는 아이템 수. 등급 안 스테이지에 랜덤으로 나뉘어 들어감
//   time = 모래시계 (시간 +20초, 그 스테이지만), gold = 금 (최대 에너지 +1, 계속 유지)
//   게임 중 랜덤한 때·자리에 나타났다가 몇 초 뒤 사라짐`]]);

patch('game.js', [
  [`  const MAX_GOLD = 6;           // 금은 6개까지 쌓임 → 최대 에너지 9`,
   `  const MAX_GOLD = 12;          // 게임 전체의 금 수 (2+3+3+4) → 최대 에너지 15
  const ITEM_LIFE = 8;          // 아이템이 나타나 있는 시간 (초). 마지막 2.5초는 깜빡임`],
  [`  function setupItems(n) {
    board.querySelectorAll('.item').forEach((e) => e.remove());
    state.items = new Map();
    const cfg = TIERS[tierOf(n).tier].items || { time: 0, gold: 0 };
    const starts = new Set(state.hazards.filter((h) => h.type !== 'sweep').map((h) => idx(h.x, h.y)));
    const spots = [];
    state.tiles.forEach((t, i) => { if (t === '.' && i !== idx(state.px, state.py) && !starts.has(i)) spots.push(i); });
    const rand = seeded(n + 101);
    for (let i = spots.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [spots[i], spots[j]] = [spots[j], spots[i]]; }
    // 앞자리부터 금 → 모래시계. 이미 먹은 금 자리는 비워 둠
    const taken = progress.goldTaken[n] || 0;
    const place = (kind, at) => {
      const el = document.createElement('div');
      el.className = \`item \${kind}\`;
      el.style.setProperty('--x', at % COLS);
      el.style.setProperty('--y', Math.floor(at / COLS));
      el.innerHTML = ICONS[kind];
      board.insertBefore(el, playerEl);
      state.items.set(at, { kind, el });
    };
    let k = 0;
    for (let g = 0; g < cfg.gold && k < spots.length; g++, k++) if (g >= taken) place('gold', spots[k]);
    for (let t = 0; t < cfg.time && k < spots.length; t++, k++) place('time', spots[k]);
  }`,
  `  // 등급 안에서 아이템이 나오는 스테이지: 등급마다 랜덤으로 정해 둠 (금은 먹은 스테이지에서 다시 안 나오게 고정)
  function itemStages(tier, kind, count) {
    const first = tierStart(tier);
    const list = TIERS[tier].stages.map((_, i) => first + i);
    const rand = seeded(1000 + tier * 10 + (kind === 'gold' ? 1 : 0));
    for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; }
    return list.slice(0, count);
  }

  function setupItems(n) {
    board.querySelectorAll('.item').forEach((e) => e.remove());
    state.items = new Map();
    state.itemPlan = [];
    const { tier } = tierOf(n);
    const cfg = TIERS[tier].items || { time: 0, gold: 0 };
    // 나타나는 때는 판마다 랜덤 (시작 3초 뒤 ~ 제한시간의 절반쯤)
    const when = () => 3 + Math.random() * Math.max(2, Math.min(state.def.time * 0.5, 30) - 3);
    if (itemStages(tier, 'time', cfg.time).includes(n)) state.itemPlan.push({ kind: 'time', at: when() });
    if (itemStages(tier, 'gold', cfg.gold).includes(n) && !progress.goldTaken[n]) state.itemPlan.push({ kind: 'gold', at: when() });
  }

  // 때가 되면 빈 바닥에 나타나고, ITEM_LIFE초가 지나면 사라짐
  function updateItems() {
    state.itemPlan.forEach((p) => { if (!p.shown && state.clock >= p.at) { p.shown = true; spawnItem(p.kind); } });
    state.items.forEach((it, i) => {
      const left = it.until - state.clock;
      if (left <= 0) {
        state.items.delete(i);
        it.el.classList.add('gone');
        setTimeout(() => it.el.remove(), 300);
      } else if (left <= 2.5) it.el.classList.add('fading');
    });
  }

  function spawnItem(kind) {
    const red = redMap();
    const pool = [];
    state.tiles.forEach((t, i) => {
      const far = Math.max(Math.abs(i % COLS - state.px), Math.abs(Math.floor(i / COLS) - state.py)) >= 2; // 볼 바로 옆은 피함
      if (t === '.' && red[i] === 0 && far && !state.items.has(i)) pool.push(i);
    });
    if (!pool.length) return;
    const at = pool[Math.floor(Math.random() * pool.length)];
    const el = document.createElement('div');
    el.className = \`item \${kind}\`;
    el.style.setProperty('--x', at % COLS);
    el.style.setProperty('--y', Math.floor(at / COLS));
    el.innerHTML = ICONS[kind];
    board.insertBefore(el, playerEl);
    state.items.set(at, { kind, el, until: state.clock + ITEM_LIFE });
    sfx.itemAppear();
  }`],
  [`      updateTilt(dt);
      if (state.shuffleLeft > 0) {`, `      updateTilt(dt);
      updateItems();
      if (state.shuffleLeft > 0) {`],
  // 에너지 칸이 많으면 가늘게
  [`    return Array.from({ length: max }, (_, i) => \`<i class="pip\${i < n ? ' on' : ''}"></i>\`).join('');`,
   `    const thin = max > 9 ? ' thin' : '';
    return Array.from({ length: max }, (_, i) => \`<i class="pip\${thin}\${i < n ? ' on' : ''}"></i>\`).join('');`],
]);

