  [`.item.got { animation: item-got 0.45s ease-out forwards; }`,
   `.item { animation: item-pop 0.35s ease-out; }
.item.fading { animation: item-blink 0.25s steps(2, jump-none) infinite alternate; } /* 곧 사라짐 */
