@keyframes item-pop { from { scale: 0; } 70% { scale: 1.25; } to { scale: 1; } }
@keyframes item-blink { from { opacity: 1; } to { opacity: 0.25; } }
@keyframes item-gone { to { scale: 0.3; opacity: 0; } }`],
  [`.lives .pip.on {`, `.lives .pip.thin { width: 5px; }
.lives .pip.on {`],
]);
console.log('ok');

