input.content:
// 볼을 진짜 3D 구처럼 굴리기 (게임·시연 화면 공용)
// - Orb.mount(el)                    .orb 안에 표면 그림(SVG)을 넣음
// - Orb.roll(el, dx, dy, ms, linear) 한 칸 굴러감: 이동 방향으로 실제 굴러간 각도만큼 3D로 회전하며 ms 동안 다시 그림
//                                    (linear = 기울기로 이어서 굴러갈 때. 아니면 칸 이동처럼 감속)
// 표면 무늬(띠·가는 선·움푹 팬 자국·반짝이·표식)를 회전 행렬로 돌린 뒤 화면에 비춘 모습을 그림
// → 가운데는 크고 빠르게, 가장자리로 갈수록 납작하게 눌리고(타원) 느려지다가 뒤로 넘어가면 안 보임 (속이 꽉 찬 쇠공)
// 좌표: x 오른쪽, y 아래(화면), z 화면 밖(보는 사람 쪽)
(() => {
  const NS = 'http://www.w3.org/2000/svg';
  const R_DRAW = 47;          // SVG(0~100)에서 볼 반지름
  // 한 칸에 굴러가는 각도 (실제 비율은 약 180°. 무늬가 제자리처럼 보이지 않게 조금 적게)
  const ROLL_PER_CELL = 2.6;

  // 3×3 행렬
  const mul = (a, b) => a.map((row) => [0, 1, 2].map((j) => row[0] * b[0][j] + row[1] * b[1][j] + row[2] * b[2][j]));
  const apply = (m, v) => [0, 1, 2].map((i) => m[i][0] * v[0] + m[i][1] * v[1] + m[i][2] * v[2]);
  // 축 k(단위 벡터) 기준 θ 회전 (로드리게스)
  function axisRot(k, t) {
    const [x, y, z] = k;
    const c = Math.cos(t), s = Math.sin(t), C = 1 - c;
    return [
      [c + x * x * C, x * y * C - z * s, x * z * C + y * s],
      [y * x * C + z * s, c + y * y * C, y * z * C - x * s],
      [z * x * C - y * s, z * y * C + x * s, c + z * z * C],
    ];
  }
  const norm = (v) => { const l = Math.hypot(...v) || 1; return v.map((x) => x / l); };

  // 대원(공을 한 바퀴 두르는 원) 위의 점들
  const greatCircle = (n, count) => {
    n = norm(n);
    const u = norm(Math.abs(n[0]) < 0.9 ? [0, -n[2], n[1]] : [-n[2], 0, n[0]]);
    const w = [n[1] * u[2] - n[2] * u[1], n[2] * u[0] - n[0] * u[2], n[0] * u[1] - n[1] * u[0]];
    return Array.from({ length: count + 1 }, (_, i) => {
      const a = (i / count) * Math.PI * 2;
      return [u[0] * Math.cos(a) + w[0] * Math.sin(a), u[1] * Math.cos(a) + w[1] * Math.sin(a), u[2] * Math.cos(a) + w[2] * Math.sin(a)];
    });
  };
  // 구 위에 고르게 퍼진 점 (피보나치 구)
  const spread = (count, turn) => Array.from({ length: count }, (_, i) => {
    const y = 1 - (2 * (i + 0.5)) / count;
    const r = Math.sqrt(1 - y * y);
    const a = i * 2.39996 + turn;
    return [r * Math.cos(a), y, r * Math.sin(a)];
  });

  // 굵은 띠: 짧은 조각으로 나눠서 조각마다 굵기를 바꿈 → 가장자리로 돌아가면 가늘어짐 (원근)
  const BAND = greatCircle([0.3, 1, 0.2], 40);
  const LINE = greatCircle([1, -0.2, 0.5], 48);     // 가는 선
  const PITS = spread(22, 0.7);                      // 움푹 팬 자국 (쇠공 표면)
  const SPARKS = spread(12, 0);                      // 반짝이 점 (금이 될수록 반짝)
  const MARK = norm([-0.1, 0.25, 0.96]);             // 표식 점 — 처음엔 앞쪽에 보이게

  const proj = (v) => [50 + v[0] * R_DRAW, 50 + v[1] * R_DRAW];
  const easeOut = (p) => 1 - Math.pow(1 - p, 3);    // 칸 이동(감속)과 같은 느낌

  // 구 표면의 작은 원: 가장자리로 갈수록 바깥 방향으로 납작한 타원
  function disc(e, q, r) {
    if (q[2] <= 0.02) { e.setAttribute('opacity', '0'); return; }
    const [x, y] = proj(q);
    const ang = (Math.atan2(q[1], q[0]) * 180) / Math.PI;
    e.setAttribute('cx', x.toFixed(1));
    e.setAttribute('cy', y.toFixed(1));
    e.setAttribute('rx', (r * Math.max(0.15, q[2])).toFixed(2)); // 바깥 방향(지름 방향)으로 눌림
    e.setAttribute('ry', r.toFixed(2));
    e.setAttribute('transform', `rotate(${ang.toFixed(0)} ${x.toFixed(1)} ${y.toFixed(1)})`);
    e.setAttribute('opacity', Math.min(1, 0.25 + q[2]).toFixed(2));
  }

  function draw(el, m) {
    const o = el._orb;
    // 띠 조각
    let prev = apply(m, BAND[0]);
    for (let i = 1; i < BAND.length; i++) {
      const q = apply(m, BAND[i]);
      const seg = o.band[i - 1];
      const z = (prev[2] + q[2]) / 2;
      if (z <= 0) seg.setAttribute('opacity', '0');
      else {
        const [x1, y1] = proj(prev), [x2, y2] = proj(q);
        seg.setAttribute('x1', x1.toFixed(1)); seg.setAttribute('y1', y1.toFixed(1));
        seg.setAttribute('x2', x2.toFixed(1)); seg.setAttribute('y2', y2.toFixed(1));
        seg.setAttribute('stroke-width', (1.2 + 7 * Math.sqrt(z)).toFixed(2));
        seg.setAttribute('opacity', Math.min(1, 0.3 + z).toFixed(2));
      }
      prev = q;
    }
    // 가는 선 (앞쪽만)
    let d = '', on = false;
    LINE.forEach((p) => {
      const q = apply(m, p);
      if (q[2] > 0) { const [x, y] = proj(q); d += `${on ? 'L' : 'M'}${x.toFixed(1)} ${y.toFixed(1)}`; on = true; } else on = false;
    });
