    PITS.forEach((p, i) => disc(o.pits[i], apply(m, p), 3.4));
    SPARKS.forEach((p, i) => disc(o.dots[i], apply(m, p), 1.6));
    disc(o.mark, apply(m, MARK), 6.5);
  }

