S="C:/Users/gitas/AppData/Local/Temp/claude/d--Gitasin/e41bd2c9-8f84-437a-aa66-b564d304f382/scratchpad"; head -24 "$S/cdp-tiltfall.mjs" > "$S/cdp-e3.mjs"; cat >> "$S/cdp-e3.mjs" <<'EOF'
  await send('Page.enable'); await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
  await send('Page.navigate', { url: 'file:///D:/Gitasin/cybercube/www/index.html' });
  await sleep(800);
  await ev(`(() => { const stars = {}; for (let i = 0; i < 47; i++) stars[i] = 2; localStorage.setItem('cybercube.progress', JSON.stringify({ stars, best: {}, name: 'T', sound: false, tab: 0, gold: 2, energy: 5 })); localStorage.setItem('cybercube.hideIntro', '1'); localStorage.setItem('cybercube.lang', 'ko'); return 1; })()`);
  await send('Page.reload'); await sleep(1200);
  await ev(`TIERS[0].tilt.flat = [99, 99]; document.querySelectorAll('#stageGrid .stage-btn')[11].click()`); await sleep(2400);
  const S = (e) => ev(`(() => { const s = __cc(); return ${e}; })()`);
  console.log('E12 start', await S(`s.lives + '/' + s.maxLives`));
  const rg = await gaps('right');
  const row = rg.find((r) => r > 0) ?? rg[0];
  await S(`(s.invincible = 999, 1)`);
  for (let k = 0; k < 14; k++) { const p = (await pos()).split(' ').map(Number); if (p[0] === 3 && p[1] === row) break; const dx = Math.sign(3 - p[0]), dy = Math.sign(row - p[1]); await key(({ '1,0': 'd', '-1,0': 'a', '0,1': 's', '0,-1': 'w', '1,1': 'c', '-1,1': 'z', '1,-1': 'e', '-1,-1': 'q' })[dx + ',' + dy]); }
  console.log('at', await pos(), 'gap row', row);
  await S(`(s.invincible = 0, s.tiltLeft = 0, s.tiltPhase = 'flat', s.tiltCfg = { ...s.tiltCfg, angle: [3, 3], dirs: ['h'], tilted: [5, 5] }, s.tiltBonus = 0, Math.random = () => 0.9, 1)`);
  for (let t = 0; t < 8; t++) { await sleep(300); console.log('3deg t' + ((t + 1) * 0.3).toFixed(1), await S(`[s.phase, s.px, s.py, s.rollVel.toFixed(2), s.lives].join(' ')`)); }
  console.log('saved energy', await ev(`JSON.parse(localStorage.getItem('cybercube.progress')).energy`));
  // 평평해진 뒤 굴러가던 힘
  await S(`(s.tiltLeft = 0.6, s.tiltPhase = 'flat', s.tiltCfg = { ...s.tiltCfg, angle: [6, 6], tilted: [0.9, 0.9], flat: [99, 99] }, Math.random = () => 0.1, 1)`);
  for (let t = 0; t < 10; t++) { await sleep(250); console.log('coast t' + ((t + 1) * 0.25).toFixed(2), await S(`[s.phase, s.px, s.py, s.tiltX, s.rollVel.toFixed(2)].join(' ')`)); }
  await ev(`document.getElementById('backBtn').click()`); await sleep(400);
  await ev(`document.querySelectorAll('#stageGrid .stage-btn')[0].click()`); await sleep(2400);
  console.log('E1 start (이어짐)', await S(`s.lives + '/' + s.maxLives`));
  // 볼 굴러가는 중 모습
  await S(`(s.invincible = 999, 1)`);
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 3, mobile: true }); await sleep(300);
  for (const k of ['w', 'd']) {
    await ev(`document.dispatchEvent(new KeyboardEvent('keydown', { key: '${k}' }))`);
    for (const ms of [40, 80, 160]) {
      await sleep(ms === 40 ? 40 : 40);
      const r = await ev(`(() => { const r = document.getElementById('player').getBoundingClientRect(); return [r.left, r.top, r.width, r.height]; })()`);
      writeFileSync(`${DIR}/roll-${k}-${ms}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png', clip: { x: r[0] - 4, y: r[1] - 4, width: r[2] + 8, height: r[3] + 8, scale: 1 } })).result.data, 'base64'));
    }
    await sleep(300);
  }
  console.log('errors:', errors.length ? errors : 'none');
} catch (e) { console.log('ERROR', e.stack); } finally { ws?.close(); edge.kill(); }
EOF
