const fs = require('fs');
const W = 'D:/Gitasin/cybercube/www/';
const patch = (p, rep) => {
  let s = fs.readFileSync(W + p, 'utf8');
  for (const [a, b] of rep) {
    if (s.split(a).length !== 2) throw new Error(p + ' miss ' + a.slice(0, 80));
    s = s.replace(a, () => b);
  }
  fs.writeFileSync(W + p, s);
};

patch('game.js', [
  // 초록에서 시작
  [`        tiles.push(ch === 'P' ? '.' : ch);
      }
    });`, `        tiles.push(ch === 'P' ? '.' : ch);
      }
    });
    // 초록이 있으면 원래 시작 지점에서 가장 가까운 초록 칸에서 시작 (떨어져도 여기서 다시)
    let bestG = -1, bestD = Infinity;
    tiles.forEach((t, i) => {
      if (t !== 'G') return;
      const d = Math.hypot(i % COLS - px, Math.floor(i / COLS) - py) - Math.floor(i / COLS) * 0.001; // 같으면 아래 줄 쪽
      if (d < bestD) { bestD = d; bestG = i; }
    });
    if (bestG >= 0) { px = bestG % COLS; py = Math.floor(bestG / COLS); }`],
  // 평평할 때 직접 움직이면 굴러가던 힘은 멈춤
  [`    window.Orb.roll(playerEl, dx, dy, glide > 0 ? glide * 1000 : dx && dy ? 280 : 230);`,
   `    if (!glide && !state.tiltX && !state.tiltY) state.rollVel = 0; // 평평할 때 직접 움직이면 굴러가던 힘은 멈춤
    window.Orb.roll(playerEl, dx, dy, glide > 0 ? glide * 1000 : dx && dy ? 280 : 230);`],
  // 떨어지면 굴러가던 힘 초기화
  [`    st.phase = 'falling';
    st.drag = null;`, `    st.phase = 'falling';
    st.drag = null;
    st.rollVel = 0; // 다시 나타나면 처음부터
    st.rollAcc = 0;`],
  [`  window.tiltVisual = tiltVisual;`, `  window.tiltVisual = tiltVisual;
  window.__cc = () => state; // 시험용 (자동 시험에서 상태 확인)`],
  [`        state.tiltPhase = 'flat';
        setTilt(0, 0);
        state.rollAcc = 0;
        state.rollVel = 0;`, `        state.tiltPhase = 'flat';
        setTilt(0, 0); // 굴러가던 힘(rollVel)은 남겨서 조금 더 굴러가다 멈춤 (coast)`],
  [`    if (!state.tiltX && !state.tiltY) return;
    if (state.rollWait > 0) { state.rollWait -= dt; return; }
    // 중력처럼 점점 빨라짐: 가속도·최고 속도 모두 기울기에 비례 (5° → 최고 2칸/초, 10° → 4칸/초, 최대 5칸/초)`,
   `    if (!state.tiltX && !state.tiltY) { coast(dt); return; }
    if (state.rollWait > 0) { state.rollWait -= dt; return; }
    // 중력처럼 점점 빨라짐: 작은 기울기도 금방 굴러가게 (3° → 최고 약 3칸/초, 10° → 5칸/초, 최대 6칸/초)`],
  [`    state.rollVel = Math.min(Math.min(5, a * 0.4), state.rollVel + a * 0.45 * dt);
