  function rollOn([dx, dy], dt) {
    state.rollAcc += state.rollVel * dt;
    if (state.rollAcc < 1) return;
    state.rollAcc -= 1;
    if (!inside(state.px + dx, state.py + dy)) fallOff(dx, dy);
    else move(dx, dy, Math.min(0.7, Math.max(0.12, 1 / state.rollVel))); // 다음 칸까지 이어서 굴러감
