  [`    const ratio = Math.max(0, state.timeLeft / state.def.time);`, `    const ratio = Math.min(1, Math.max(0, state.timeLeft / state.def.time));`],
  [`      state.lives = cfg.rewardedLife ?? 1;`, `      state.lives = Math.min(MAX_LIVES, cfg.rewardedLife ?? 3);`],
  [`t('watchAdLife', { n: cfg.rewardedLife ?? 1 }) : t('watchAdTime', { n: cfg.rewardedTime ?? 15 })`,
   `t('watchAdLife', { n: cfg.rewardedLife ?? 3 }) : t('watchAdTime', { n: cfg.rewardedTime ?? 60 })`],
  [`      state.timeLeft += cfg.rewardedTime ?? 15;`, `      state.timeLeft += cfg.rewardedTime ?? 60;`],
]);

