  await send('Page.reload'); await sleep(1200);
  const S = (e) => ev(`(() => { const s = __cc(); return ${e}; })()`);
  const vis = () => ev(`(() => { const p = document.getElementById('player'); return p.className + ' op ' + getComputedStyle(p).opacity + ' shatter ' + !!document.querySelector('.shard, .player.shatter'); })()`);
