  const g = await S(`JSON.stringify(Object.fromEntries(['top','bottom','left','right'].map(k => [k, s.walls[k].map((w, i) => w ? -1 : i).filter(i => i >= 0)])))`);
  console.log('gaps', g);
  const gp = JSON.parse(g);
  const [side, i] = gp.left.length ? ['left', gp.left[0]] : gp.right.length ? ['right', gp.right[0]] : gp.top.length ? ['top', gp.top[0]] : ['bottom', gp.bottom[0]];
  const [x, y, k] = side === 'left' ? [0, i, 'a'] : side === 'right' ? [5, i, 'd'] : side === 'top' ? [i, 0, 'w'] : [i, 7, 's'];
  await S(`(s.px = ${x}, s.py = ${y}, s.lives = 1, s.invincible = 99, 1)`); await sleep(300);
  await S(`(s.invincible = 0, 1)`);
  await key(k, 100);
  for (const t of [400, 900, 1400, 4500]) { await sleep(t === 400 ? 300 : t === 4500 ? 3100 : 500); console.log('t' + t, await S(`s.phase + ' ' + s.px + ',' + s.py`), await vis()); }
  console.log('buttons', await ev(`[...document.querySelectorAll('#modalButtons button')].map(b => b.textContent).join(' | ')`));
  await ev(`[...document.querySelectorAll('#modalButtons button')].find(b => b.textContent.includes('광고')).click()`); await sleep(6500); await ev(`document.getElementById('adClose').click()`); await sleep(800);
  console.log('after ad', await S(`s.phase + ' ' + s.px + ',' + s.py + ' lives ' + s.lives`), await vis());
  writeFileSync(`${DIR}/after-ad.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'));
  console.log('errors:', errors.length ? errors : 'none');
} catch (e) { console.log('ERROR', e.stack); } finally { ws?.close(); edge.kill(); }
